const GLOSSARY_CATS = ["すべて", ...DOMAINS.map(d => d.id)];

const BANK_COUNT = Object.fromEntries(DOMAINS.map(d => [d.id, BANK.filter(q=>q.d===d.id).length]));

// ===== 選択肢シャッフルの中核 =====
// 問題から安定キーを生成
function qKey(q) {
  const base = (q.d || "") + "|" + (q.q || "");
  let h = 0;
  for (let i = 0; i < base.length; i++) { h = (h * 31 + base.charCodeAt(i)) | 0; }
  return "q" + (h >>> 0).toString(36);
}
// 決定的乱数（seedから0..1）
function mulberry32(seed) {
  return function () {
    seed |= 0; seed = (seed + 0x6D2B79F5) | 0;
    let t = Math.imul(seed ^ (seed >>> 15), 1 | seed);
    t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t;
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
}
// シードから順列を作る（Fisher-Yates）
function permFromSeed(n, seed) {
  const rng = mulberry32(seed);
  const idx = Array.from({ length: n }, (_, i) => i);
  for (let i = n - 1; i > 0; i--) {
    const j = Math.floor(rng() * (i + 1));
    [idx[i], idx[j]] = [idx[j], idx[i]];
  }
  return idx;
}
// 問題の選択肢をシャッフルする（正解の位置は偏らない）
// salt を変えると同じ問題でも別の並びになる（クイズ⇔模試⇔セッションで分散）
function shuffleChoices(q, lang, salt = 0, legacy = false) {
  const opts = lang === "en" ? (q.oEn || q.o) : q.o;
  const n = opts.length;
  // キーから決定的シード
  let h = 0; const base = qKey(q) + "|" + salt;
  for (let i = 0; i < base.length; i++) { h = (h * 33 + base.charCodeAt(i)) | 0; }
  let perm = permFromSeed(n, h >>> 0);
  // 正解の位置は A〜D のどこにも同じ確率で来る（以前は「正解を先頭に置かない」ようにしていたが、A が正解にならないと分かると1択減らせてしまうのでやめた）
  if (legacy) { let tries = 0; while (perm[0] === q.a && tries < 8) { h = (h * 1103515245 + 12345) | 0; perm = permFromSeed(n, h >>> 0); tries++; } if (perm[0] === q.a) { const target = 1 + ((h >>> 0) % (n - 1)); [perm[0], perm[target]] = [perm[target], perm[0]]; } } // 変更前の途中保存から再開したときだけ、以前の並べ方を再現する
  const shuffledOpts = perm.map(i => opts[i]);
  const newAnswer = perm.indexOf(q.a);
  const oeSrc = lang === "en" ? (q.oeEn || q.oe) : q.oe;
  return { opts: shuffledOpts, answer: newAnswer, oe: (oeSrc && oeSrc.length === n) ? perm.map(i => oeSrc[i]) : null, ref: (lang === "en" ? (q.refEn || q.ref) : q.ref) || null };
}

// ===== 永続化 =====
async function loadState() {
  try { const r = await window.storage.get(STORE_KEY); return r ? JSON.parse(r.value) : null; } catch { return null; }
}
async function saveState(s) { try { await window.storage.set(STORE_KEY, JSON.stringify(s)); } catch {} }
async function loadReview() {
  try { const r = await window.storage.get(REVIEW_KEY); return r ? JSON.parse(r.value) : {}; } catch { return {}; }
}
async function saveReview(obj) { try { await window.storage.set(REVIEW_KEY, JSON.stringify(obj)); } catch {} }
async function addReviewItems(questions) {
  const cur = await loadReview();
  questions.forEach(q => {
    const k = qKey(q);
    const prev = cur[k];
    cur[k] = { q, miss: (prev?.miss || 0) + 1, added: prev?.added || Date.now() };
  });
  await saveReview(cur);
  return cur;
}
async function clearReviewItem(q) {
  const cur = await loadReview();
  const k = qKey(q);
  if (cur[k]) { delete cur[k]; await saveReview(cur); }
  return cur;
}

function L(obj, key, lang) { if (lang === "en") return obj[key + "En"] || obj[key]; return obj[key]; }
function domName(id, lang) { return lang === "en" ? DOM_NAME_EN[id] : DOM_NAME[id]; }
function shuffle(arr) { const a = [...arr]; for (let i = a.length - 1; i > 0; i--) { const j = Math.floor(Math.random() * (i + 1)); [a[i], a[j]] = [a[j], a[i]]; } return a; }

const GH900_EXAM_CASES = [{"id":"gh900-1","title":{"ja":"ケース：小規模開発チームのコラボレーションワークフロー","en":"Case: Collaboration Workflow for a Small Development Team"},"body":{"ja":["あるスタートアップの開発チーム（6名）が、Web アプリを GitHub 上の単一リポジトリで開発している。これまでは全員が main ブランチに直接コミットしていたため、壊れたコードが本番へ混入する事故が続いていた。","チームリードは GitHub Flow を採用することにした。作業は必ず短命なフィーチャーブランチで行い、Pull Request（PR）を通じて main へ統合する方針とする。変更内容の議論やタスク管理には Issue を使い、PR と Issue を相互にリンクさせたい。","品質を担保するため、main への直接 push を禁止し、マージ前に最低 1 名のレビュー承認と CI（GitHub Actions）チェックの成功を必須にしたい。これらは Branch protection rule（またはルールセット）で強制する。","レビューでは、コードの特定行に対するコメントや変更提案（suggested change）を活用し、レビュアーは Approve / Request changes / Comment のいずれかで意思表示する。会話が解決したら PR をマージする。","また、繰り返し発生する定型作業（バグ報告のフォーマットなど）を統一するため、Issue テンプレートや PR テンプレートの導入も検討している。担当者は @メンションで通知し、ラベルで分類する。"],"en":["A startup's development team (6 members) builds a web app in a single GitHub repository. Until now everyone committed directly to the main branch, which repeatedly let broken code reach production.","The team lead decides to adopt GitHub Flow: all work must happen on short-lived feature branches and be merged into main through Pull Requests (PRs). Issues will be used to discuss changes and track tasks, and the team wants PRs and Issues cross-linked.","To protect quality, direct pushes to main must be blocked, and before merging each PR needs at least one approving review and a passing CI (GitHub Actions) check. These will be enforced with a branch protection rule (or ruleset).","During review, reviewers use line-level comments and suggested changes, and express their decision with Approve, Request changes, or Comment. Once conversations are resolved, the PR is merged.","The team also considers Issue templates and PR templates to standardize recurring routine work (such as bug-report formatting). Assignees are notified via @mentions, and items are categorized with labels."]},"tables":[{"title":{"ja":"GitHub Flow の主要ステップ","en":"Key Steps of GitHub Flow"},"headers":{"ja":["ステップ","操作","目的"],"en":["Step","Action","Purpose"]},"rows":{"ja":[["1","ブランチを作成","main から独立して安全に作業する"],["2","コミットして push","変更を記録し共有する"],["3","Pull Request を開く","レビューと議論を依頼する"],["4","レビューと CI","品質を確認する"],["5","main へマージしデプロイ","変更を統合する"]],"en":[["1","Create a branch","Work safely, isolated from main"],["2","Commit and push","Record and share changes"],["3","Open a Pull Request","Request review and discussion"],["4","Review and CI","Verify quality"],["5","Merge to main and deploy","Integrate the changes"]]}}],"questions":[{"n":1,"q":{"ja":"main への直接 push を禁止し、マージ前にレビュー承認と CI 成功を必須にするために最も適切な機能はどれか。","en":"Which feature best enforces blocking direct pushes to main and requiring an approving review plus a passing CI before merge?"},"options":[{"label":{"ja":"Branch protection rule（ブランチ保護ルール）／ルールセット","en":"Branch protection rule / ruleset"},"exp":{"ja":"正解。保護対象ブランチへの直接 push 禁止、必須レビュー数、必須ステータスチェックなどを強制できる。","en":"Correct. It can enforce blocking direct pushes, required number of reviews, and required status checks on the protected branch."}},{"label":{"ja":"リポジトリの README にルールを書く","en":"Write the rules in the repository README"},"exp":{"ja":"不正解。README は説明であり、技術的な強制力はない。","en":"Incorrect. A README is documentation and has no technical enforcement."}},{"label":{"ja":"全員をリポジトリの管理者(Admin)にする","en":"Make everyone a repository Admin"},"exp":{"ja":"不正解。権限を上げても制約は増えず、むしろ直接 push を防げない。","en":"Incorrect. Elevating permissions adds no constraints and does not prevent direct pushes."}},{"label":{"ja":"Issue テンプレートを追加する","en":"Add an Issue template"},"exp":{"ja":"不正解。Issue テンプレートは報告様式の統一用で、マージ制御はできない。","en":"Incorrect. Issue templates standardize reporting; they cannot control merges."}}],"a":0},{"n":2,"q":{"ja":"PR がマージされたときに、関連する Issue を自動的にクローズするために PR の説明に書く記述はどれか。","en":"What should you write in a PR description so that the linked Issue closes automatically when the PR is merged?"},"options":[{"label":{"ja":"「関連 Issue: #123」とだけ書く","en":"Just write \"Related issue: #123\""},"exp":{"ja":"不正解。単に番号を参照するだけではリンクはされるが自動クローズはされない。","en":"Incorrect. Merely referencing the number links it but does not auto-close it."}},{"label":{"ja":"「Closes #123」などのクローズ用キーワードを書く","en":"Write a closing keyword such as \"Closes #123\""},"exp":{"ja":"正解。close / closes / fixes / resolves などのキーワード＋Issue 番号で、マージ時に自動クローズされる。","en":"Correct. Keywords like close/closes/fixes/resolves plus the issue number auto-close it on merge."}},{"label":{"ja":"Issue にラベル「done」を付ける","en":"Add a \"done\" label to the Issue"},"exp":{"ja":"不正解。ラベルは分類用で、クローズ動作とは連動しない。","en":"Incorrect. Labels are for categorization and do not trigger closing."}},{"label":{"ja":"Issue を Draft PR に変換する","en":"Convert the Issue into a Draft PR"},"exp":{"ja":"不正解。Issue を PR に変換する機能はなく、自動クローズの手段でもない。","en":"Incorrect. There is no such conversion, and it is not a way to auto-close."}}],"a":1},{"n":3,"q":{"ja":"レビュアーが「この変更ではマージすべきでない、修正が必要」と明確に示すには、どのレビュー操作を選ぶべきか。","en":"To clearly indicate \"this should not be merged as-is; changes are needed,\" which review action should a reviewer choose?"},"options":[{"label":{"ja":"Comment（コメントのみ）","en":"Comment (comment only)"},"exp":{"ja":"不正解。Comment は承認も却下もしない中立的なフィードバックで、ブロックの意思表示にはならない。","en":"Incorrect. Comment is neutral feedback that neither approves nor blocks."}},{"label":{"ja":"Approve（承認）","en":"Approve"},"exp":{"ja":"不正解。Approve はマージを支持する意思表示で、逆の意味になる。","en":"Incorrect. Approve signals support for merging, the opposite intent."}},{"label":{"ja":"Request changes（変更を要求）","en":"Request changes"},"exp":{"ja":"正解。修正が必要という明確な意思表示で、保護ルール次第でマージをブロックできる。","en":"Correct. It explicitly requests changes and, depending on protection rules, can block the merge."}},{"label":{"ja":"PR を Draft に戻す","en":"Convert the PR back to Draft"},"exp":{"ja":"不正解。Draft 化は作成者側の状態管理で、レビュアーの正式な評価手段ではない。","en":"Incorrect. Converting to Draft is the author's state management, not a reviewer's formal verdict."}}],"a":2},{"n":4,"q":{"ja":"GitHub Flow に沿った日々の作業手順として最も適切なものはどれか。","en":"Which is the most appropriate day-to-day workflow that follows GitHub Flow?"},"options":[{"label":{"ja":"main に直接コミットし、問題があれば後で revert する","en":"Commit directly to main and revert later if there are problems"},"exp":{"ja":"不正解。直接コミットは本ケースで避けたい事故原因であり、GitHub Flow の趣旨に反する。","en":"Incorrect. Direct commits are exactly the incident cause the team wants to avoid and contradict GitHub Flow."}},{"label":{"ja":"long-lived な dev ブランチにためて月末に一括で main へマージ","en":"Accumulate on a long-lived dev branch and bulk-merge into main monthly"},"exp":{"ja":"不正解。GitHub Flow は短命ブランチと小さな頻繁な統合を推奨する。","en":"Incorrect. GitHub Flow favors short-lived branches and small, frequent integration."}},{"label":{"ja":"作業ごとに main からブランチを切り、PR を開いてレビューと CI 後にマージする","en":"Branch from main per task, open a PR, and merge after review and CI"},"exp":{"ja":"正解。GitHub Flow の標準的な流れそのもので、本ケースの要件に合致する。","en":"Correct. This is the standard GitHub Flow and matches the case requirements."}},{"label":{"ja":"各自がリポジトリを個別に持ち、統合は行わない","en":"Everyone keeps a separate repository and never integrates"},"exp":{"ja":"不正解。統合しなければ共同開発が成立せず、方針に反する。","en":"Incorrect. Without integration there is no collaboration, contrary to the policy."}}],"a":2}]},{"id":"gh900-2","title":{"ja":"ケース：Organization / Enterprise の運用とセキュリティ","en":"Case: Organization / Enterprise Administration and Security"},"body":{"ja":["ある企業が GitHub を全社導入し、Organization を作成して複数チームのリポジトリを集約する。セキュリティ管理者は、権限を最小権限の原則で割り当てたいと考えている。","Organization では、メンバーへの基本ロール（Owner / Member）に加え、リポジトリ単位のアクセス権（Read / Triage / Write / Maintain / Admin）を Team を通じて付与する運用を想定している。個人ごとの直接付与ではなく Team ベースで管理したい。","コンプライアンス要件として、Organization の全メンバーに二要素認証（2FA）を必須化する。パスワードレス強化のため passkey も推奨する。監査ログでアクセス状況を追跡する。","さらに、社員のアイデンティティを会社の IdP で一元管理し、GitHub 上の個人アカウントと切り離したい。そこで Enterprise Managed Users（EMU）を含む Enterprise 契約を検討している。","生成 AI 活用のため GitHub Copilot も導入するが、どのファイル／リポジトリで使えるか、公開コードに一致する提案の扱いなどを Organization の Copilot ポリシーで制御したい。リポジトリの可視性（public / private / internal）も適切に設定する。"],"en":["A company rolls out GitHub company-wide, creating an Organization to consolidate multiple teams' repositories. The security admin wants to assign permissions following the principle of least privilege.","In the Organization, in addition to base member roles (Owner / Member), repository-level access (Read / Triage / Write / Maintain / Admin) will be granted through Teams. They prefer Team-based management over direct per-user grants.","For compliance, two-factor authentication (2FA) will be required for all Organization members. To strengthen passwordless sign-in, passkeys are also recommended. Access is tracked via the audit log.","The company also wants to centrally manage employee identities in its IdP and decouple them from personal GitHub accounts. It is therefore evaluating an Enterprise plan including Enterprise Managed Users (EMU).","To leverage generative AI, GitHub Copilot will be adopted, but the company wants to control where it can be used and how suggestions matching public code are handled, via the Organization's Copilot policies. Repository visibility (public / private / internal) will also be set appropriately."]},"tables":[{"title":{"ja":"リポジトリ権限ロールの主な違い","en":"Key Differences Among Repository Permission Roles"},"headers":{"ja":["ロール","主にできること","想定利用者"],"en":["Role","Main capabilities","Typical user"]},"rows":{"ja":[["Read","閲覧・クローン・Issue 作成","利害関係者・閲覧者"],["Triage","Issue/PR の管理（コード変更なし）","コミュニティ整理担当"],["Write","push・ブランチ作成・PR マージ","コントリビューター"],["Maintain","一部設定管理（機微設定は除く）","プロジェクト管理者"],["Admin","全設定・権限・削除","リポジトリ責任者"]],"en":[["Read","View, clone, open issues","Stakeholders / viewers"],["Triage","Manage issues/PRs (no code write)","Community triager"],["Write","Push, create branches, merge PRs","Contributors"],["Maintain","Some settings (not sensitive ones)","Project managers"],["Admin","All settings, access, deletion","Repository owner"]]}},{"title":{"ja":"リポジトリの可視性","en":"Repository Visibility"},"headers":{"ja":["可視性","閲覧できる範囲"],"en":["Visibility","Who can see it"]},"rows":{"ja":[["Public","インターネット上の誰でも"],["Private","明示的にアクセスを与えられた人のみ"],["Internal","同じ Enterprise のメンバー全員"]],"en":[["Public","Anyone on the internet"],["Private","Only people explicitly granted access"],["Internal","All members of the same Enterprise"]]}}],"questions":[{"n":1,"q":{"ja":"コード変更はさせず、Issue や PR のラベル付け・アサインなどの整理だけを許可したい。最小権限に合うロールはどれか。","en":"You want to allow triaging issues and PRs (labeling, assigning) but no code changes. Which role fits least privilege?"},"options":[{"label":{"ja":"Write","en":"Write"},"exp":{"ja":"不正解。Write は push などコード変更が可能で、要件より過大。","en":"Incorrect. Write allows pushing code, exceeding the requirement."}},{"label":{"ja":"Triage","en":"Triage"},"exp":{"ja":"正解。Triage は Issue/PR の管理はできるがコードの書き込みはできず、要件に合致する。","en":"Correct. Triage can manage issues/PRs but cannot write code, matching the requirement."}},{"label":{"ja":"Admin","en":"Admin"},"exp":{"ja":"不正解。Admin は全設定にアクセスでき、最小権限に反する。","en":"Incorrect. Admin has full settings access, violating least privilege."}},{"label":{"ja":"Read","en":"Read"},"exp":{"ja":"不正解。Read では Issue/PR のラベル付けやアサインなどの整理操作ができない。","en":"Incorrect. Read cannot perform triage actions like labeling or assigning."}}],"a":1},{"n":2,"q":{"ja":"社員の GitHub アイデンティティを会社の IdP で一元管理し、個人アカウントと切り離してプロビジョニングしたい。最も適した仕組みはどれか。","en":"You want employees' GitHub identities managed centrally by the company IdP, provisioned and decoupled from personal accounts. Which mechanism fits best?"},"options":[{"label":{"ja":"各社員が個人アカウントを作り Organization に招待する","en":"Each employee creates a personal account and is invited to the Organization"},"exp":{"ja":"不正解。個人アカウント運用は IdP による一元管理・切り離しの要件を満たさない。","en":"Incorrect. Personal accounts do not meet centralized IdP management and decoupling."}},{"label":{"ja":"Enterprise Managed Users（EMU）","en":"Enterprise Managed Users (EMU)"},"exp":{"ja":"正解。EMU は IdP がユーザーを管理・プロビジョニングし、個人アカウントと分離された企業専用ユーザーを提供する。","en":"Correct. EMU has the IdP manage/provision users, providing enterprise-only accounts decoupled from personal ones."}},{"label":{"ja":"リポジトリを public にする","en":"Make repositories public"},"exp":{"ja":"不正解。可視性の話でアイデンティティ管理とは無関係。","en":"Incorrect. Visibility is unrelated to identity management."}},{"label":{"ja":"全員に Admin ロールを付与する","en":"Grant everyone the Admin role"},"exp":{"ja":"不正解。権限付与の話であり、IdP 連携やアカウント分離を実現しない。","en":"Incorrect. This is about permissions and does not provide IdP integration or account separation."}}],"a":1},{"n":3,"q":{"ja":"同じ Enterprise 内のメンバー全員には見せたいが、インターネット全体には公開したくない社内共通リポジトリの可視性はどれか。","en":"For a shared internal repository visible to all members of the same Enterprise but not to the whole internet, which visibility should you use?"},"options":[{"label":{"ja":"Public","en":"Public"},"exp":{"ja":"不正解。Public はインターネット上の誰でも閲覧でき、非公開の要件に反する。","en":"Incorrect. Public is visible to anyone on the internet, violating the requirement."}},{"label":{"ja":"Private","en":"Private"},"exp":{"ja":"不正解。Private は明示的に許可した人のみで、Enterprise 全員には自動で見えない。","en":"Incorrect. Private is only for explicitly granted people, not automatically all Enterprise members."}},{"label":{"ja":"Internal","en":"Internal"},"exp":{"ja":"正解。Internal は同一 Enterprise のメンバー全員に見え、外部には非公開で要件に合致する。","en":"Correct. Internal is visible to all members of the same Enterprise and hidden externally, matching the requirement."}},{"label":{"ja":"Archived","en":"Archived"},"exp":{"ja":"不正解。Archived は読み取り専用化の状態であり、可視性の種類ではない。","en":"Incorrect. Archived is a read-only state, not a visibility level."}}],"a":2},{"n":4,"q":{"ja":"全メンバーへのアカウント保護強化として、Organization レベルで最初に実施すべき設定はどれか。","en":"To strengthen account protection for all members, which setting should be enforced first at the Organization level?"},"options":[{"label":{"ja":"二要素認証（2FA）の必須化","en":"Require two-factor authentication (2FA)"},"exp":{"ja":"正解。2FA 必須化はアカウント乗っ取り対策の基本で、Organization 全体に適用できる。passkey は更なる強化策。","en":"Correct. Requiring 2FA is a fundamental defense against account takeover and can apply org-wide; passkeys further strengthen it."}},{"label":{"ja":"全リポジトリを public にする","en":"Make all repositories public"},"exp":{"ja":"不正解。可視性を上げると情報漏えいリスクが増え、保護強化にならない。","en":"Incorrect. Increasing visibility raises leakage risk and does not strengthen protection."}},{"label":{"ja":"監査ログを削除する","en":"Delete the audit log"},"exp":{"ja":"不正解。監査ログは追跡に不可欠で、削除は逆効果。","en":"Incorrect. The audit log is essential for tracking; deleting it is counterproductive."}},{"label":{"ja":"全員のパスワードを共有する","en":"Share one password among everyone"},"exp":{"ja":"不正解。認証情報の共有は重大なセキュリティ違反。","en":"Incorrect. Sharing credentials is a serious security violation."}}],"a":0}]},{"id":"gh900-3","title":{"ja":"ケース：モダン開発とコミュニティ／プロジェクト管理","en":"Case: Modern Development and Community / Project Management"},"body":{"ja":["あるオープンソースプロジェクトが GitHub のモダンな開発機能を活用して生産性とコミュニティの健全性を高めようとしている。メンテナは自動化と可視化を重視している。","CI/CD を自動化するため、GitHub Actions を用いてワークフローを構築する。push や pull_request などのイベントをトリガーに、テストやビルドを自動実行したい。ワークフローは YAML でリポジトリ内に定義する。","貢献者がローカル環境構築に時間を取られないよう、ブラウザ上でクラウド開発環境を起動できる GitHub Codespaces を導入する。加えて、コーディング支援として GitHub Copilot を活用する。","作業の可視化とロードマップ管理には GitHub Projects（かんばん・テーブル・ロードマップのビュー）を用い、Issue や PR をアイテムとして進捗をトラッキングする。","コミュニティ運営では、行動規範（CODE_OF_CONDUCT）や CONTRIBUTING、ライセンスなどコミュニティヘルスファイルを整備する。資金支援には GitHub Sponsors、再利用可能なアクションの配布には GitHub Marketplace の利用を検討している。"],"en":["An open-source project wants to use GitHub's modern development features to boost productivity and community health. The maintainers emphasize automation and visibility.","To automate CI/CD, they build workflows with GitHub Actions. Triggered by events such as push and pull_request, tests and builds should run automatically. Workflows are defined in YAML inside the repository.","So contributors don't spend time on local setup, they adopt GitHub Codespaces, a cloud development environment launched in the browser. They also use GitHub Copilot for coding assistance.","For visibility and roadmap management they use GitHub Projects (board, table, and roadmap views), tracking progress with Issues and PRs as items.","For community operations they add community health files such as CODE_OF_CONDUCT, CONTRIBUTING, and a license. They consider GitHub Sponsors for funding and GitHub Marketplace for distributing reusable actions."]},"tables":[{"title":{"ja":"GitHub Actions の基本用語","en":"Core GitHub Actions Terminology"},"headers":{"ja":["用語","意味"],"en":["Term","Meaning"]},"rows":{"ja":[["Workflow","自動化プロセス全体（YAML で定義）"],["Event","実行のきっかけ（push, pull_request など）"],["Job","同一ランナー上で実行されるステップの集まり"],["Runner","ワークフローを実行するサーバー"],["Action","再利用可能な処理単位"]],"en":[["Workflow","The whole automated process (defined in YAML)"],["Event","What triggers a run (push, pull_request, etc.)"],["Job","A set of steps run on the same runner"],["Runner","The server that executes the workflow"],["Action","A reusable unit of work"]]}}],"questions":[{"n":1,"q":{"ja":"push や pull_request をきっかけにテストを自動実行するワークフローを定義する場所と形式はどれか。","en":"Where and in what format do you define a workflow that auto-runs tests on push or pull_request?"},"options":[{"label":{"ja":"リポジトリの .github/workflows 配下に YAML ファイルで定義する","en":"As a YAML file under the repository's .github/workflows directory"},"exp":{"ja":"正解。GitHub Actions のワークフローは .github/workflows 内の YAML で定義し、イベントで起動する。","en":"Correct. Actions workflows are defined as YAML in .github/workflows and triggered by events."}},{"label":{"ja":"README.md にシェルスクリプトを書く","en":"Write a shell script in README.md"},"exp":{"ja":"不正解。README はドキュメントで、Actions を起動しない。","en":"Incorrect. The README is documentation and does not trigger Actions."}},{"label":{"ja":"各開発者のローカル PC に cron を設定する","en":"Set up cron on each developer's local PC"},"exp":{"ja":"不正解。ローカル cron は GitHub のイベントと連動せず、共有もされない。","en":"Incorrect. Local cron is not tied to GitHub events and is not shared."}},{"label":{"ja":"Issue に手順をコメントする","en":"Comment the steps on an Issue"},"exp":{"ja":"不正解。Issue コメントは実行環境ではない。","en":"Incorrect. An Issue comment is not an execution environment."}}],"a":0},{"n":2,"q":{"ja":"新しい貢献者がローカル環境構築なしに、ブラウザからすぐにコーディングを始められるようにする機能はどれか。","en":"Which feature lets new contributors start coding immediately from the browser without local environment setup?"},"options":[{"label":{"ja":"GitHub Pages","en":"GitHub Pages"},"exp":{"ja":"不正解。Pages は静的サイトのホスティングで、開発環境ではない。","en":"Incorrect. Pages hosts static sites; it is not a dev environment."}},{"label":{"ja":"GitHub Codespaces","en":"GitHub Codespaces"},"exp":{"ja":"正解。Codespaces はクラウド上のオンデマンド開発環境をブラウザ等で提供し、ローカル構築が不要。","en":"Correct. Codespaces provides an on-demand cloud dev environment in the browser, no local setup needed."}},{"label":{"ja":"GitHub Sponsors","en":"GitHub Sponsors"},"exp":{"ja":"不正解。Sponsors は資金支援の仕組みで開発環境ではない。","en":"Incorrect. Sponsors is a funding mechanism, not a dev environment."}},{"label":{"ja":"GitHub Projects","en":"GitHub Projects"},"exp":{"ja":"不正解。Projects は進捗管理ツールで、コーディング環境は提供しない。","en":"Incorrect. Projects is for tracking work, not a coding environment."}}],"a":1},{"n":3,"q":{"ja":"Issue や PR をアイテムとして扱い、かんばん・テーブル・ロードマップのビューで進捗を可視化・管理するのに最適な機能はどれか。","en":"Which feature best visualizes and manages progress with Issues and PRs as items across board, table, and roadmap views?"},"options":[{"label":{"ja":"GitHub Actions","en":"GitHub Actions"},"exp":{"ja":"不正解。Actions は CI/CD 自動化で、進捗可視化のビュー機能ではない。","en":"Incorrect. Actions is CI/CD automation, not a progress-visualization view."}},{"label":{"ja":"GitHub Marketplace","en":"GitHub Marketplace"},"exp":{"ja":"不正解。Marketplace はアプリやアクションの配布・入手の場。","en":"Incorrect. Marketplace is for distributing/obtaining apps and actions."}},{"label":{"ja":"GitHub Projects","en":"GitHub Projects"},"exp":{"ja":"正解。Projects は Issue/PR をアイテム化し、ボード・テーブル・ロードマップで可視化・管理できる。","en":"Correct. Projects turns Issues/PRs into items and manages them in board, table, and roadmap views."}},{"label":{"ja":"GitHub Copilot","en":"GitHub Copilot"},"exp":{"ja":"不正解。Copilot はコーディング支援 AI で、プロジェクト管理ツールではない。","en":"Incorrect. Copilot is an AI coding assistant, not a project management tool."}}],"a":2},{"n":4,"q":{"ja":"オープンソースプロジェクトの利用者に貢献方法を案内し、参加のハードルを下げるために追加すべきコミュニティヘルスファイルはどれか。","en":"Which community health file should you add to guide users on how to contribute and lower the barrier to participation?"},"options":[{"label":{"ja":"package-lock.json","en":"package-lock.json"},"exp":{"ja":"不正解。依存関係のロックファイルで、貢献ガイドではない。","en":"Incorrect. A dependency lock file, not a contribution guide."}},{"label":{"ja":".gitignore","en":".gitignore"},"exp":{"ja":"不正解。追跡除外の設定であり、貢献方法の案内ではない。","en":"Incorrect. It excludes files from tracking; it does not guide contribution."}},{"label":{"ja":"CONTRIBUTING（.md）","en":"CONTRIBUTING (.md)"},"exp":{"ja":"正解。CONTRIBUTING は貢献手順・規約を案内し、Issue/PR 作成時にも参照され参加を促す。","en":"Correct. CONTRIBUTING explains how to contribute and is surfaced when opening Issues/PRs, encouraging participation."}},{"label":{"ja":"workflow.yml","en":"workflow.yml"},"exp":{"ja":"不正解。Actions のワークフロー定義で、貢献ガイドではない。","en":"Incorrect. An Actions workflow definition, not a contribution guide."}}],"a":2}]}];

function ExamCaseRunner({ cases, lang, onBack, backRef, ck }) {
  const caseDone = useDoneSet("case:" + (ck || "x"));
  const g = (o) => (o && (o[lang] != null ? o[lang] : o.ja));
  const clist = Array.isArray(cases) ? cases : [cases];
  const [pick, setPick] = useState(clist.length === 1 ? 0 : null);
  const [qi, setQi] = useState(0);
  const [answers, setAnswers] = useState({});
  const [finished, setFinished] = useState(false);

  const th = { textAlign: "left", padding: "7px 9px", background: "#EDE9E0", color: C.deep, fontSize: 11.5, fontWeight: 700, borderBottom: `1px solid ${C.mid}`, whiteSpace: "nowrap" };
  const td = { padding: "7px 9px", fontSize: 12, borderBottom: `1px solid ${C.mid}`, verticalAlign: "top", lineHeight: 1.45 };

  const openCase = (i) => { setPick(i); setQi(0); setAnswers({}); setFinished(false); };
  useEffect(() => { if (!backRef) return; backRef.current = () => { if (pick !== null && clist.length > 1) { setPick(null); setQi(0); setAnswers({}); setFinished(false); return true; } return false; }; return () => { if (backRef) backRef.current = null; }; }, [pick, backRef]);
  const backToList = () => { if (clist.length > 1) { setPick(null); setQi(0); setAnswers({}); setFinished(false); } else onBack(); };

  if (pick === null) {
    return (
      <div>
        <div style={{ display: "flex", justifyContent: "space-between", alignItems: "center", marginBottom: 10 }}>
          <button onClick={onBack} style={{ border: "none", background: "none", color: nvInk(C.primary, C.light), cursor: "pointer", fontWeight: 700, fontSize: 12.5, padding: 0 }}>{lang === "ja" ? "← 戻る" : "← Back"}</button>
        </div>
        <div style={{ fontSize: 15, fontWeight: 800, color: C.deep, marginBottom: 4 }}>{lang === "ja" ? "本試験形式ケース" : "Exam-style cases"}</div>
        <div style={{ fontSize: 12, color: "#5d6c83", marginBottom: 12 }}>{lang === "ja" ? "資料表つき・僅差4択・全選択肢に根拠解説" : "Data tables, 4 close options, rationale for each"}</div>
        {clist.map((c, i) => (
          <button key={i} onClick={() => openCase(i)}
            style={{ width: "100%", textAlign: "left", padding: "14px 15px", marginBottom: 10, borderRadius: 11,
              border: `1.5px solid ${C.primary}`, background: "#fff", cursor: "pointer", display: "flex", justifyContent: "space-between", alignItems: "center" }}>
            <span style={{ fontWeight: 700, fontSize: 13.5, color: C.deep, lineHeight: 1.45, paddingRight: 10 }}><DoneCheck on={caseDone.has(i)} onToggle={(e) => caseDone.toggle(i, e)} />{g(c.title)}</span>
            <span style={{ fontSize: 11.5, color: "#5d6c83", whiteSpace: "nowrap" }}>{c.questions.length}{lang === "ja" ? "問" : "Q"}</span>
          </button>
        ))}
      </div>
    );
  }

  const data = clist[pick];
  const qs = data.questions;
  const Q = qs[qi];
  const sel = answers[qi] != null ? answers[qi] : null;
  const choose = (i) => { if (sel !== null) return; setAnswers(a => ({ ...a, [qi]: i })); };
  const prev = () => { if (qi > 0) setQi(qi - 1); };
  const next = () => { if (qi < qs.length - 1) setQi(qi + 1); };
  const restart = () => { setQi(0); setAnswers({}); setFinished(false); };

  let correct = 0;
  for (let k = 0; k < qs.length; k++) { const a = answers[k]; if (a != null && qs[k].options[a] && qs[k].options[a].ok) correct++; }
  const answeredCount = Object.keys(answers).length;
  const rate = qs.length ? Math.round((correct / qs.length) * 100) : 0;

  const navBtn = (label, onClick, enabled, primary) => (
    <button onClick={enabled ? onClick : undefined} disabled={!enabled}
      style={{ flex: 1, padding: "11px 12px", borderRadius: 9, fontSize: 13.5, fontWeight: 700,
        cursor: enabled ? "pointer" : "default",
        border: primary ? "none" : `1.5px solid ${enabled ? C.primary : C.mid}`,
        background: primary ? (enabled ? C.primary : C.mid) : "#fff",
        color: primary ? "#fff" : (enabled ? C.primary : "#b9c4d6") }}>{label}</button>
  );

  return (
    <div>
      <div style={{ display: "flex", justifyContent: "space-between", alignItems: "center", marginBottom: 10 }}>
        <button onClick={backToList} style={{ border: "none", background: "none", color: nvInk(C.primary, C.light), cursor: "pointer", fontWeight: 700, fontSize: 12.5, padding: 0 }}>{clist.length > 1 ? (lang === "ja" ? "← ケース一覧" : "← Case list") : (lang === "ja" ? "← 戻る" : "← Back")}</button>
        {!finished && <span style={{ fontSize: 12, color: "#5d6c83" }}>{lang === "ja" ? `問 ${qi + 1} / ${qs.length}` : `Q ${qi + 1} / ${qs.length}`}</span>}
      </div>

      <div style={{ background: "#fff", border: `1px solid ${C.mid}`, borderRadius: 12, padding: 16, marginBottom: 12 }}>
        <div style={{ fontSize: 15, fontWeight: 800, color: C.deep, marginBottom: 10 }}>{g(data.title)}</div>
        <div style={{ fontSize: 11, fontWeight: 700, color: C.primary, marginBottom: 6 }}>{lang === "ja" ? "ケース本文（資料）" : "Case (materials)"}</div>
        {g(data.body).map((p, i) => (<div key={i} style={{ fontSize: 13, lineHeight: 1.7, marginBottom: 8, color: C.ink }}>{p}</div>))}
        {(data.tables || []).map((tb, ti) => (
          <div key={ti} style={{ marginTop: 12 }}>
            <div style={{ fontSize: 12.5, fontWeight: 700, color: C.deep, marginBottom: 5 }}>{g(tb.title)}</div>
            <div style={{ overflowX: "auto", border: `1px solid ${C.mid}`, borderRadius: 8 }}>
              <table style={{ borderCollapse: "collapse", width: "100%", minWidth: 320 }}>
                <thead><tr>{g(tb.headers).map((h, hi) => (<th key={hi} style={th}>{h}</th>))}</tr></thead>
                <tbody>{g(tb.rows).map((r, ri) => (<tr key={ri}>{r.map((cell, ci) => (<td key={ci} style={td}>{cell}</td>))}</tr>))}</tbody>
              </table>
            </div>
          </div>
        ))}
      </div>

      {finished ? (
        <div style={{ background: "#fff", border: `1px solid ${C.mid}`, borderRadius: 12, padding: 16 }}>
          <div style={{ textAlign: "center", marginBottom: 12 }}>
            <div style={{ fontSize: 13, color: "#5a6a85", fontWeight: 600, marginBottom: 6 }}>{lang === "ja" ? "ケース完了" : "Case complete"}</div>
            <div style={{ fontSize: 32, fontWeight: 800, color: rate >= PASS ? C.ok : C.ng }}>{rate}%</div>
            <div style={{ fontSize: 12.5, color: "#5d6c83", marginTop: 2 }}>{lang === "ja" ? `正解 ${correct} / ${qs.length} 問` : `${correct} / ${qs.length} correct`}</div>
          </div>
          <Bar pct={rate} color={rate >= PASS ? C.ok : C.ng} />
          <div style={{ display: "flex", gap: 8, marginTop: 14 }}>
            <button onClick={() => { setFinished(false); setQi(0); }} style={{ flex: 1, padding: 12, borderRadius: 9, border: `1.5px solid ${C.primary}`, background: "#fff", color: C.primary, fontSize: 14, fontWeight: 700, cursor: "pointer" }}>{lang === "ja" ? "解答を見直す" : "Review answers"}</button>
            <button onClick={restart} style={{ flex: 1, padding: 12, borderRadius: 9, border: "none", background: C.primary, color: nvInk("#ffffff", C.primary, 3), fontSize: 14, fontWeight: 700, cursor: "pointer" }}>{lang === "ja" ? "もう一度" : "Retry"}</button>
          </div>
        </div>
      ) : (
        <div style={{ background: "#fff", border: `1px solid ${C.mid}`, borderRadius: 12, padding: 16 }}>
          <div style={{ fontSize: 14.5, fontWeight: 700, marginBottom: 12, color: C.deep }}>{lang === "ja" ? `問${Q.n}. ` : `Q${Q.n}. `}{g(Q.q)}</div>
          {Q.options.map((opt, i) => {
            let bg = "#fff", bd = C.mid, col = C.ink;
            if (sel !== null) { if (opt.ok) { bg = "#E6F4EC"; bd = C.ok; col = C.ok; } else if (i === sel) { bg = "#FBEAE8"; bd = C.ng; col = C.ng; } }
            return (
              <button key={i} onClick={() => choose(i)} disabled={sel !== null}
                style={{ display: "block", width: "100%", textAlign: "left", marginBottom: 8, padding: "11px 13px", borderRadius: 9, border: `1.5px solid ${bd}`, background: bg, color: col, cursor: sel === null ? "pointer" : "default", fontSize: 13.5, lineHeight: 1.5, fontWeight: sel !== null && opt.ok ? 700 : 500 }}>
                <span style={{ fontWeight: 700, marginRight: 8 }}>{sel !== null && opt.ok ? "✓" : sel !== null && i === sel ? "✗" : "ABCD"[i]}</span>{g(opt.label)}
              </button>
            );
          })}
          {sel !== null && (
            <div style={{ marginTop: 12 }}>
              {Q.options.map((opt, i) => (
                <div key={i} style={{ background: opt.ok ? "#E6F4EC" : (i === sel ? "#FBEAE8" : C.light), borderRadius: 8, padding: "9px 11px", marginBottom: 6, fontSize: 12.5, lineHeight: 1.55 }}>
                  <span style={{ fontWeight: 700, marginRight: 6, color: opt.ok ? C.ok : (i === sel ? C.ng : "#5d6c83") }}>{"ABCD"[i]}{opt.ok ? (lang === "ja" ? "（正解）" : " (correct)") : ""}</span>{g(opt.exp)}
                </div>
              ))}
            </div>
          )}
          <div style={{ display: "flex", gap: 8, marginTop: 12 }}>
            {navBtn(lang === "ja" ? "← 前の問題" : "← Previous", prev, qi > 0, false)}
            {qi < qs.length - 1
              ? navBtn(lang === "ja" ? "次の問題 →" : "Next →", next, sel !== null, true)
              : navBtn(lang === "ja" ? "結果を見る →" : "See result →", () => setFinished(true), answeredCount === qs.length, true)}
          </div>
        </div>
      )}
    </div>
  );
}

function App() {
  const [tab, _setTab] = useState("home");
  const [tabHist, setTabHist] = useState([]);
  const backRef = useRef(null);
  const setTab = (k) => { if (k !== tab) setTabHist(h => [...h, tab]); _setTab(k); };
  const goBackTab = () => { if (backRef.current && backRef.current()) { if (typeof window !== "undefined") window.scrollTo({ top: 0, behavior: "smooth" }); return; } if (!tabHist.length) return; const prev = tabHist[tabHist.length - 1]; setTabHist(tabHist.slice(0, -1)); _setTab(prev); if (typeof window !== "undefined") window.scrollTo({ top: 0, behavior: "smooth" }); };
  const [state, setState] = useState(null);
  const [loaded, setLoaded] = useState(false);
  const [lang, setLang] = useState(certInitLang);
  const t = T[lang];

  useEffect(() => {
    loadState().then(s => {
      setState(s || { progress: {} });
      setLoaded(true);
    });
  }, []);

  const persist = (next) => { setState(next); saveState(next); };

  const record = (domId, correct) => { try { novaLogStudy(); } catch (e) {}
    setState((prev) => { const next = JSON.parse(JSON.stringify(prev)); // 同じ描画中に続けて呼ばれても（本番モードの一括採点）前の更新に積み上げる
    if (!next.progress[domId]) next.progress[domId] = { correct: 0, attempts: 0 };
    next.progress[domId].attempts++;
    if (correct) next.progress[domId].correct++;
    saveState(next); return next; });
  };

  if (!loaded) return <div style={{ padding: 40, textAlign: "center", color: C.deep }}>{t.loading}</div>;

  const TABS = [
    ["home", t.tabHome], ["quiz", t.tabQuiz], ["exam", t.tabExam], ["examcase", (lang === "en" ? "Exam Cases" : "本試験形式ケース")], ["review", t.reviewTab],
    ["diagram", t.tabDiagram], ["compare", t.tabCompare], ["confuse", t.tabConfuse], ["glossary", t.tabGlossary],
  ];

  return (
    <div style={{ fontFamily: "system-ui, sans-serif", color: C.ink, background: "#F7FBFF", minHeight: "100vh" }}>
      <div style={{ background: C.deep, color: nvInk("#ffffff", C.deep), padding: "16px 18px", display: "flex", justifyContent: "space-between", alignItems: "center" }}>
        <div>
          <div style={{ fontSize: 19, fontWeight: 700 }}>{t.appTitle}</div>
          <div style={{ fontSize: 12, marginTop: 2 }}>{t.appSub}</div>
          <div style={{ fontSize: 11, marginTop: 4 }}>{t.bankCount(BANK.length)} ・ {t.examCount(Object.keys(EXAM_SETS).length)}</div>
        </div>
        <div style={{ display: "flex", background: "rgba(255,255,255,.15)", borderRadius: 20, padding: 3 }}>
          {["ja", "en"].map(l => (
            <button key={l} onClick={() => setLang(l)}
              style={{ border: "none", cursor: "pointer", borderRadius: 16, padding: "5px 12px", fontSize: 12, fontWeight: 700,
                background: lang === l ? "#fff" : "transparent", color: lang === l ? nvInk(C.deep, "#ffffff") : "#fff" }}>
              {l === "ja" ? "日本語" : "English"}
            </button>
          ))}
        </div>
      </div>
      <div style={{ display: "flex", flexWrap: "wrap", borderBottom: `2px solid ${C.mid}`, background: C.light }}>
        {TABS.map(([k, label]) => (
          <button key={k} onClick={() => setTab(k)}
            style={{ flex: "1 1 auto", padding: "11px 8px", border: "none", cursor: "pointer",
              background: tab === k ? "#fff" : "transparent", color: tab === k ? nvInk(C.deep, "#ffffff") : C.ink,
              fontWeight: tab === k ? 700 : 500, fontSize: 13,
              borderBottom: tab === k ? `3px solid ${C.primary}` : "3px solid transparent" }}>
            {label}
          </button>
        ))}
      </div>
      {tabHist.length > 0 && (
        <button onClick={goBackTab}
          aria-label="Back"
          style={{ position: "fixed", right: 16, bottom: 104, zIndex: 45, border: `1.5px solid ${C.deep}`, cursor: "pointer", borderRadius: 22, padding: "9px 15px", background: "#fff", color: C.deep, fontSize: 12.5, fontWeight: 700, boxShadow: "0 4px 14px rgba(0,0,0,.20)" }}>
          ← {lang === "en" ? "Back" : "戻る"}
        </button>
      )}
      {tab !== "home" && (
        <button onClick={() => { setTab("home"); if (typeof window !== "undefined") window.scrollTo({ top: 0, behavior: "smooth" }); }}
          aria-label="Back to top"
          style={{ position: "fixed", right: 16, bottom: 60, zIndex: 45, border: "none", cursor: "pointer", borderRadius: 22, padding: "10px 15px", background: C.deep, color: nvInk("#ffffff", C.deep), fontSize: 12.5, fontWeight: 700, boxShadow: "0 4px 14px rgba(0,0,0,.28)" }}>
          ↑ {lang === "en" ? "Top" : "トップへ"}
        </button>
      )}
      <div style={{ padding: 16, maxWidth: 820, margin: "0 auto" }}>
        {tab === "home" && <><CertCompletion state={state} storeKey={STORE_KEY} figsKey={STORE_KEY} figsTotal={(CERT_FLOWS["GH-900"]||[]).length} bankLen={BANK.length} lang={lang} C={C} /><Home state={state} lang={lang} t={t} /></>}
        {tab === "quiz" && <Quiz onAnswer={record} lang={lang} t={t} />}
        {tab === "exam" && <Exam onAnswer={record} lang={lang} t={t} backRef={backRef} />}
        {tab === "review" && <Review lang={lang} t={t} onAnswer={record} />}
        {tab === "diagram" && <Diagrams lang={lang} t={t} />}
        {tab === "compare" && <Compare lang={lang} t={t} />}
        {tab === "confuse" && <Confuse lang={lang} t={t} />}
        {tab === "glossary" && <Glossary lang={lang} t={t} />}
        {tab === "examcase" && <ExamCaseRunner ck="GH900_EXAM_CASES" cases={GH900_EXAM_CASES} lang={lang} onBack={() => setTab("home")} backRef={backRef} />}
      </div>
    </div>
  );
}

function Home({ state, lang, t }) {
  const totals = useMemo(() => {
    let c = 0, a = 0;
    Object.values(state.progress).forEach(p => { c += p.correct; a += p.attempts; });
    return { c, a, rate: a ? Math.round((c / a) * 100) : 0 };
  }, [state]);

  const weak = useMemo(() => {
    return DOMAINS.map(d => {
      const p = state.progress[d.id] || { correct: 0, attempts: 0 };
      const rate = p.attempts ? Math.round((p.correct / p.attempts) * 100) : null;
      return { ...d, rate, attempts: p.attempts };
    }).filter(d => d.attempts > 0).sort((a, b) => a.rate - b.rate);
  }, [state]);

  return (
    <div>
      <div style={{ marginBottom: 16 }}>
        <Stat label={t.overallRate} value={`${totals.rate}%`} sub={`${totals.c}/${totals.a}${t.questionsUnit}`} color={totals.rate >= PASS ? C.ok : C.primary} />
      </div>
      <Card title={t.domMastery}>
        {DOMAINS.map(d => {
          const p = state.progress[d.id] || { correct: 0, attempts: 0 };
          const rate = p.attempts ? Math.round((p.correct / p.attempts) * 100) : 0;
          return (
            <div key={d.id} style={{ marginBottom: 12 }}>
              <div style={{ display: "flex", justifyContent: "space-between", fontSize: 12.5, marginBottom: 3 }}>
                <span style={{ fontWeight: 600 }}>
                  <span style={{ background: d.hue, color: nvInk("#ffffff", d.hue), borderRadius: 4, padding: "1px 6px", fontSize: 11, marginRight: 6 }}>{d.id}</span>
                  {domName(d.id, lang)}
                  <span style={{ color: "#5a7288", fontSize: 11, marginLeft: 6 }}>· {BANK_COUNT[d.id]}{t.questionsUnit}</span>
                </span>
                <span style={{ color: "#5b6b7d" }}>{d.range} · {p.attempts ? `${rate}%` : t.notStarted}</span>
              </div>
              <Bar pct={rate} color={d.hue} faint={!p.attempts} />
            </div>
          );
        })}
      </Card>
      {weak.length > 0 && (
        <Card title={t.weakDomains}>
          {weak.slice(0, 3).map(d => (
            <div key={d.id} style={{ fontSize: 13, padding: "6px 0", borderBottom: `1px solid ${C.light}` }}>
              <span style={{ background: d.hue, color: nvInk("#ffffff", d.hue), borderRadius: 4, padding: "1px 6px", fontSize: 11, marginRight: 6 }}>{d.id}</span>
              {domName(d.id, lang)} — <strong style={{ color: d.rate < PASS ? C.ng : C.ok }}>{d.rate}%</strong>
            </div>
          ))}
        </Card>
      )}
    </div>
  );
}

function Stat({ label, value, sub, color }) {
  return (
    <div style={{ background: "#fff", border: `1px solid ${C.mid}`, borderRadius: 12, padding: 14 }}>
      <div style={{ fontSize: 11.5, color: "#5b6b7d" }}>{label}</div>
      <div style={{ fontSize: 26, fontWeight: 800, color: color ? nvInk(color, "#ffffff", 3) : undefined }}>{value}</div>
      <div style={{ fontSize: 11, color: "#5a7288" }}>{sub}</div>
    </div>
  );
}
function Card({ title, children }) {
  return (
    <div style={{ background: "#fff", border: `1px solid ${C.mid}`, borderRadius: 12, padding: 14, marginBottom: 14 }}>
      <div style={{ fontSize: 13.5, fontWeight: 700, color: C.deep, marginBottom: 10 }}>{title}</div>
      {children}
    </div>
  );
}
function Bar({ pct, color, faint }) {
  return (
    <div style={{ background: C.light, borderRadius: 8, height: 9, overflow: "hidden" }}>
      <div style={{ width: `${pct}%`, height: "100%", background: faint ? C.mid : color, transition: "width .3s" }} />
    </div>
  );
}

function Quiz({ onAnswer, lang, t }) {
  const [filter, setFilter] = useState("ALL");
  const [orderMode, setOrderMode] = useState("seq");
  const [order, setOrder] = useState([]);
  const [pos, setPos] = useState(0);
  const [sel, setSel] = useState(null);
  const [answeredMap, setAnsweredMap] = useState({});
  const slot = useQuizSlot("gh900_study_v1:quiz_resume");
  const domDone = useDoneSet("gh900_study_v1:quiz_resume:dc");
  const resumeRef = useRef(null);
  // セッションごとに選択肢の並びを変えるためのソルト
  const [sessionSalt] = useState(() => Math.floor(Math.random() * 100000));

  const pool = useMemo(() => {
    let idxs = filter === "ALL" ? BANK.map((_, i) => i) : BANK.map((_, i) => i).filter(i => BANK[i].d === filter);
    if (orderMode === "random") idxs = shuffle(idxs);
    return idxs;
  }, [filter, orderMode]);

  useEffect(() => {
    if (resumeRef.current) {
      const r = resumeRef.current; resumeRef.current = null;
      setOrder(r.order && r.order.length ? r.order : pool);
      setPos(r.pos || 0); setSel(r.sel == null ? null : r.sel); setAnsweredMap(r.answeredMap || {});
      return;
    }
    setOrder(pool); setPos(0); setSel(null); setAnsweredMap({});
  }, [pool]);
  const doResume = async () => {
    const d = await slot.read(); if (!d) return;
    resumeRef.current = { order: d.order, pos: d.pos, sel: d.sel, answeredMap: d.answeredMap };
    setFilter(d.filter || "ALL"); setOrderMode(d.orderMode || "seq");
    setOrder(d.order && d.order.length ? d.order : order);
    setPos(d.pos || 0); setSel(d.sel == null ? null : d.sel); setAnsweredMap(d.answeredMap || {});
  };

  const poolCount = order.length;
  const qi = order.length ? order[pos] : -1;
  const Q = qi >= 0 ? BANK[qi] : null;
  // 選択肢をシャッフル（クイズはsalt="quiz"+session）。フックは早期returnより前で必ず呼ぶ。
  const sc = useMemo(() => (Q ? shuffleChoices(Q, lang, "quiz" + sessionSalt) : { opts: [], answer: -1 }), [Q, lang, sessionSalt]);
  if (order.length === 0) return null;
  const opts = sc.opts;
  const ans = sc.answer;

  const choose = (i) => {
    if (sel !== null) return;
    setSel(i);
    const correct = i === ans;
    setAnsweredMap(m => ({ ...m, [pos]: i }));
    onAnswer(Q.d, correct);
  };
  const goPrev = () => {
    if (pos === 0) return;
    const np = pos - 1;
    setPos(np);
    setSel(answeredMap[np] !== undefined ? answeredMap[np] : null);
  };
  const goNext = () => {
    const np = pos + 1 >= poolCount ? 0 : pos + 1;
    setPos(np);
    setSel(answeredMap[np] !== undefined ? answeredMap[np] : null);
  };

  return (
    <div>
      <div style={{ display: "flex", alignItems: "center", gap: 8, marginBottom: 12, flexWrap: "wrap" }}>
        <button onClick={async () => { await slot.save({ filter, orderMode, order, pos, sel, answeredMap }, filter === "ALL" ? t.allFields : filter); }}
          style={{ padding: "6px 14px", borderRadius: 8, border: `1.5px solid ${C.primary}`, background: "#fff", color: C.primary, fontWeight: 700, fontSize: 12.5, cursor: "pointer" }}>
          {slot.meta ? (lang === "en" ? "💾 Saved" : "💾 保存済") : (lang === "en" ? "💾 Save" : "💾 セーブ")}
        </button>
        {slot.meta && (
          <>
            <button onClick={doResume} style={{ padding: "6px 14px", borderRadius: 8, border: "none", background: C.primary, color: nvInk("#ffffff", C.primary), fontWeight: 700, fontSize: 12.5, cursor: "pointer" }}>{lang === "en" ? "▶ Resume" : "▶ 続きから"}</button>
            <span style={{ fontSize: 11, color: "#5a7288" }}>{slot.meta.label}{slot.meta.label ? "／" : ""}{saveStamp(slot.meta.t)}</span>
            <button onClick={() => slot.remove()} style={{ marginLeft: "auto", padding: "6px 10px", borderRadius: 8, border: "1px solid #cbd5e1", background: "#fff", color: "#7d93a8", fontSize: 11, cursor: "pointer" }}>{lang === "en" ? "Delete" : "削除"}</button>
          </>
        )}
      </div>
      <div style={{ display: "flex", justifyContent: "space-between", alignItems: "center", marginBottom: 12 }}>
        <span style={{ fontSize: 12.5, color: "#5a7288" }}>{t.allFields} {poolCount}{t.questionsUnit}</span>
        <div style={{ display: "inline-flex", background: C.light, borderRadius: 20, padding: 4 }}>
          {[["seq", t.orderSeq], ["random", t.orderRandom]].map(([k, label]) => (
            <button key={k} onClick={() => setOrderMode(k)}
              style={{ border: "none", cursor: "pointer", borderRadius: 16, padding: "6px 18px", fontSize: 13, fontWeight: 700,
                background: orderMode === k ? "#fff" : "transparent",
                color: orderMode === k ? nvInk(C.deep, "#ffffff") : nvInk("#7d93a8", C.mid),
                boxShadow: orderMode === k ? "0 1px 3px rgba(0,0,0,.12)" : "none" }}>
              {label}
            </button>
          ))}
        </div>
      </div>

      <div style={{ display: "flex", gap: 6, flexWrap: "wrap", marginBottom: 12 }}>
        {["ALL", ...DOMAINS.map(d => d.id)].map(k => (
          <button key={k} onClick={() => setFilter(k)}
            style={{ display: "inline-flex", alignItems: "center", padding: "7px 16px", borderRadius: 20, fontSize: 13, cursor: "pointer",
              border: `1.5px solid ${filter === k ? C.primary : C.mid}`,
              background: filter === k ? C.primary : "#fff", color: filter === k ? nvInk("#ffffff", C.primary) : nvInk(C.ink, "#ffffff"), fontWeight: 600 }}><DoneCheck on={domDone.has(k)} onToggle={(e) => domDone.toggle(k, e)} /><span>{k === "ALL" ? t.allFields : k}</span></button>
        ))}
      </div>

      <div style={{ background: "#fff", border: `1px solid ${C.mid}`, borderRadius: 12, padding: 16 }}>
        <div style={{ fontSize: 11, color: nvInk("#ffffff", DOM_HUE[Q.d]), background: DOM_HUE[Q.d], display: "inline-block", borderRadius: 4, padding: "2px 8px", marginBottom: 10 }}>
          {Q.d} · {domName(Q.d, lang)}
        </div>
        <div style={{ fontSize: 16, fontWeight: 600, marginBottom: 16, lineHeight: 1.5, display: "flex", alignItems: "flex-start", gap: 6 }}><span style={{ flex: 1 }}>{L(Q, "q", lang)}</span><StarButton id={"q#" + novaQHash(Q.q || Q.qEn || "")} text={Q.q || Q.qEn} scope={lang === "en" ? "Quiz" : "クイズ"} /></div>
        {opts.map((opt, i) => {
          let bg = "#fff", bd = C.mid, col = C.ink;
          if (sel !== null) {
            if (i === ans) { bg = "#E6F4EF"; bd = C.ok; col = C.ok; }
            else if (i === sel) { bg = "#FBEAE8"; bd = C.ng; col = C.ng; }
          }
          return (
            <button key={i} onClick={() => choose(i)} disabled={sel !== null}
              style={{ display: "block", width: "100%", textAlign: "left", marginBottom: 10, padding: "14px 16px",
                borderRadius: 10, border: `1.5px solid ${bd}`, background: bg, color: col,
                cursor: sel === null ? "pointer" : "default", fontSize: 14, lineHeight: 1.4,
                fontWeight: sel !== null && i === ans ? 700 : 500 }}>
              <span style={{ fontWeight: 700, marginRight: 10 }}>{sel !== null && (i === ans) ? "✓" : sel !== null && (i === sel) ? "✗" : "ABCD"[i]}</span>{opt}
              {sel !== null && sc.oe && sc.oe[i] ? <div style={{ marginTop: 6, marginLeft: 24, fontSize: 12, lineHeight: 1.5, fontWeight: 500, color: i === ans ? C.ok : (i === sel ? C.ng : "#8a94a6") }}>{(i === ans ? "◎ " : "✗ ") + sc.oe[i]}</div> : null}
            </button>
          );
        })}
        {sel !== null && (
          <div style={{ marginTop: 12 }}>
            <div style={{ background: C.light, borderRadius: 9, padding: 12, fontSize: 13, lineHeight: 1.55 }}>
              <strong style={{ color: nvInk(sel === ans ? C.ok : C.ng, C.light) }}>{sel === ans ? t.correct : t.incorrect}</strong>
              ・{t.answerIs("ABCD"[ans])}{L(Q, "e", lang)}{sc.ref ? <span style={{ display: "block", marginTop: 6, fontSize: 11.5, color: "#8a94a6" }}>{sc.ref}</span> : null}
            </div>
          </div>
        )}
      <div style={{ display: "flex", justifyContent: "space-between", alignItems: "center", marginTop: 14 }}>
        <button onClick={goPrev} disabled={pos === 0}
          style={{ padding: "10px 30px", borderRadius: 9, fontSize: 13.5, fontWeight: 600,
            border: `1.5px solid ${C.mid}`, background: pos === 0 ? C.light : "#fff",
            color: pos === 0 ? "#a9bccf" : nvInk(C.ink, "#ffffff"), cursor: pos === 0 ? "not-allowed" : "pointer" }}>
          {lang === "en" ? "← Previous" : "← 前の問題"}
        </button>
        <span style={{ fontSize: 13, color: "#5a7288" }}>{pos + 1} / {poolCount}</span>
        <button onClick={goNext} style={{ padding: "10px 30px", borderRadius: 9, fontSize: 13.5, fontWeight: 600, border: `1.5px solid ${C.primary}`, background: "#fff", color: C.primary, cursor: "pointer" }}>{t.nextQ}</button>
      </div>
      </div>
    </div>
  );
}

const GH900_MULTI = [{"d":"D1","q":"田中さんはGitとGitHubを初めて学んでおり、ローカルでの変更を記録し、最終的にリモートリポジトリへ反映するまでの一連の流れを理解しようとしています。次の記述のうち、Gitの基本的なコマンドの働きについて正しいものを2つ選んでください。","qEn":"Tanaka is new to Git and GitHub and is learning the basic flow from recording local changes to reflecting them in a remote repository. Select 2 statements that correctly describe basic Git commands.","o":["git add はステージングエリアに変更を追加する","git commit はステージング済みの変更をローカル履歴として記録する","git push はリモートリポジトリを自動的にフォークする","git clone は既存リモートリポジトリの変更を強制的に上書きする"],"oEn":["git add stages changes into the staging area","git commit records staged changes into local history","git push automatically forks the remote repository","git clone forcibly overwrites an existing remote repository's changes"],"a":[0,1],"n":2,"e":"git add はステージング、git commit はローカル履歴への記録を行う。フォークやクローンの強制上書きは誤り。","eEn":"git add stages changes; git commit records them to local history. Forking and force-overwrite claims are incorrect."},{"d":"D1","q":"新入社員向けのGit研修で、ワーキングディレクトリ・ステージングエリア・ローカルリポジトリという3つの領域の役割を説明することになりました。次の記述のうち、これらの領域について正しいものを2つ選んでください。","qEn":"In a Git training for new hires, you need to explain the roles of the working directory, staging area, and local repository. Select 2 correct statements about these areas.","o":["ワーキングディレクトリは実際に編集中のファイルが存在する場所である","ステージングエリアはコミット対象として選んだ変更を一時的に保持する","ローカルリポジトリ(.git)はGitHub上にのみ存在し手元のPCには存在しない","コミットするとステージングエリアの内容はワーキングディレクトリからも削除される"],"oEn":["The working directory is where files being actively edited exist","The staging area temporarily holds changes selected for the next commit","The local repository (.git) exists only on GitHub, not on the local machine","Committing also deletes the staged content from the working directory"],"a":[0,1],"n":2,"e":".git はローカルにも存在する。コミットしてもワーキングディレクトリのファイルは削除されない。","eEn":"The .git repository exists locally too, and committing does not remove files from the working directory."},{"d":"D2","q":"OSSプロジェクトのメンテナが、外部の貢献者向けに貢献方法のガイドラインと、脆弱性を発見した際の報告手順を、リポジトリ内の専用ファイルとして明示的に用意したいと考えています。この目的に合致するファイルを2つ選んでください。","qEn":"An OSS maintainer wants dedicated repository files that document contribution guidelines and how to report vulnerabilities. Select 2 files that match this purpose.","o":["CONTRIBUTING.md — 貢献方法のガイドラインを記載する","SECURITY.md — 脆弱性の報告方法を記載する",".gitignore — Gitの追跡対象から除外するパターンを定義する","CODEOWNERS — 特定パスの必須レビュアーを指定する"],"oEn":["CONTRIBUTING.md — documents how to contribute","SECURITY.md — documents how to report vulnerabilities",".gitignore — defines patterns excluded from Git tracking","CODEOWNERS — designates required reviewers for specific paths"],"a":[0,1],"n":2,"e":"貢献方法はCONTRIBUTING.md、脆弱性報告手順はSECURITY.mdで示す。他の2つは別目的のファイル。","eEn":"CONTRIBUTING.md covers contribution guidance and SECURITY.md covers vulnerability reporting; the other two files serve different purposes."},{"d":"D2","q":"プロジェクトリーダーが、新しいメンバーがリポジトリの管理機能を正しく理解しているかを確認するため、次の記述のうち正しいものを2つ選ぶよう求めました。テンプレートリポジトリとフォークの違いに注目してください。","qEn":"A project lead asked the team to confirm their understanding of repository management features by selecting 2 correct statements, focusing on the difference between template repositories and forks.","o":["テンプレートリポジトリから新規作成すると、元のコミット履歴を引き継がずに作成される","フォークしたリポジトリは元リポジトリとの関係を保持し、Pull Requestを送信できる","フォークすると元リポジトリのIssueもすべて自動的に複製される","リポジトリのInsightsタブは常にソースコードの内容そのものを表示する"],"oEn":["Creating from a template repository does not carry over the original commit history","A forked repository keeps its relationship to the original and can send pull requests","Forking automatically duplicates all issues from the original repository","A repository's Insights tab always displays the raw source code content"],"a":[0,1],"n":2,"e":"テンプレート利用は履歴なしで作成、フォークは元との関係を保持しPRを送れる。Issue複製やInsightsの説明は誤り。","eEn":"Templates create history-free copies; forks retain a relationship enabling pull requests. Issue duplication and the Insights claim are incorrect."},{"d":"D3","q":"開発者がPull Requestの説明文に「Closes #42」と記載し、そのPRがデフォルトブランチにマージされました。このIssueとPull Requestの連携について、正しい記述を2つ選んでください。","qEn":"A developer wrote \"Closes #42\" in a pull request description, and the PR was merged into the default branch. Select 2 correct statements about this issue-PR linking behavior.","o":["PRがマージされると、リンクされたIssue #42は自動的にクローズされる","Closes、Fixes、Resolves などのキーワードはIssueをリンクし自動クローズをトリガーできる","コミットメッセージに同様のキーワードを書いても、Issueのクローズには一切効果がない","自動クローズが機能するには、PRとIssueの作成者が同一人物である必要がある"],"oEn":["When the PR is merged, the linked issue #42 is automatically closed","Keywords like Closes, Fixes, and Resolves can link an issue and trigger auto-close","Using the same keywords in a commit message has no effect on closing the issue","Auto-close only works if the PR and issue were created by the same person"],"a":[0,1],"n":2,"e":"Closes等のキーワードはPRの説明文だけでなくコミットメッセージでも機能し、作成者が同一である必要はない。","eEn":"Closing keywords also work in commit messages, not just PR descriptions, and same-author is not a requirement."},{"d":"D3","q":"レビュアーとしてPull Requestを確認する機会が増えたエンジニアに向けて、GitHubのコラボレーション機能に関する社内研修資料を新しく作成しています。次の記述のうち、内容として正しいものを3つ選んでください。","qEn":"You are preparing training materials on GitHub collaboration features for engineers who now review pull requests more often. Select 3 correct statements.","o":["レビューでは Approve、Request changes、Comment のいずれかを選択して提出できる","ラベルを使うとIssueやPRを種類や優先度などで分類できる","GitHub Discussionsは主にコードの脆弱性を自動スキャンする機能である","Draft Pull Requestは、レビュー準備がまだ整っていない作業中の状態を示せる"],"oEn":["A review can be submitted as Approve, Request changes, or Comment","Labels let you categorize issues and PRs by type or priority","GitHub Discussions is primarily an automatic code vulnerability scanning feature","A draft pull request can signal work still in progress and not ready for review"],"a":[0,1,3],"n":3,"e":"レビューの3種類の選択、ラベルによる分類、Draft PRの用途はいずれも正しい。Discussionsはスキャン機能ではなく議論の場。","eEn":"The three review types, label-based categorization, and draft PR usage are all correct; Discussions is a discussion space, not a scanner."},{"d":"D4","q":"チームがリポジトリにCI(継続的インテグレーション)を導入するため、GitHub Actionsのワークフローを初めて設定しようとしています。ワークフローの基本構造について、正しい記述を2つ選んでください。","qEn":"A team is setting up its first GitHub Actions workflow to introduce CI in a repository. Select 2 correct statements about the basic structure of a workflow.","o":["ワークフローファイルは .github/workflows ディレクトリにYAML形式で配置する","on キーワードで push や pull_request など、ワークフローをトリガーするイベントを定義する","1つのワークフローファイルには1つのjobしか定義できない","runs-on はワークフロー全体に対して一度だけ、リポジトリ設定側で定義する"],"oEn":["Workflow files are placed as YAML under the .github/workflows directory","The on keyword defines triggering events such as push or pull_request","A single workflow file can define only one job","runs-on is defined once for the whole workflow, in repository settings"],"a":[0,1],"n":2,"e":"ワークフローは.github/workflows配下のYAMLで、onでトリガーを定義する。1ワークフローに複数job定義でき、runs-onはjobごとに指定する。","eEn":"Workflows live as YAML under .github/workflows and on defines triggers. A workflow can define multiple jobs, and runs-on is set per job."},{"d":"D4","q":"リモートで働くエンジニアが、手元に開発環境を構築せず、ブラウザだけで開発を進められる環境を探しています。GitHub Codespacesとgithub.devの違いに関する記述のうち、正しいものを2つ選んでください。","qEn":"A remote engineer is looking for an environment where development can proceed from just a browser. Select 2 correct statements about the difference between GitHub Codespaces and github.dev.","o":["GitHub Codespacesはクラウド上でホストされる、設定済みの開発環境を提供する","github.devはフル機能のクラウド開発環境で、ターミナルからビルドやテスト実行が可能である","GitHub Copilotが提案したコードは常に自動的にコミットされる","Codespacesの開発環境はdevcontainerの構成でカスタマイズできる"],"oEn":["GitHub Codespaces provides a cloud-hosted, preconfigured development environment","github.dev is a full cloud development environment with terminal build and test execution","Code suggested by GitHub Copilot is always committed automatically","A Codespaces environment can be customized via a devcontainer configuration"],"a":[0,3],"n":2,"e":"Codespacesはdevcontainerでカスタマイズ可能なクラウド環境。github.devはターミナル実行のない軽量エディタで、Copilotは自動コミットしない。","eEn":"Codespaces is a customizable cloud environment via devcontainer; github.dev is a lightweight editor without a terminal, and Copilot does not auto-commit."},{"d":"D5","q":"複数のリポジトリにまたがるタスクをスプレッドシートではなくGitHub上で一元管理したいチームリーダーが、GitHub Projectsの導入を検討しています。GitHub Projectsの機能に関する正しい記述を2つ選んでください。","qEn":"A team lead who wants to centrally manage tasks across multiple repositories is considering adopting GitHub Projects. Select 2 correct statements about GitHub Projects features.","o":["ボード、テーブル、ロードマップなど複数のレイアウトを切り替えて表示できる","カスタムフィールドを追加してステータスや優先度などの独自情報を管理できる","Projectsに含められるのは特定の1つのリポジトリのIssueのみである","新しいProjectsはProjects (Classic)とまったく同じ機能・操作方法である"],"oEn":["You can switch between multiple layouts such as board, table, and roadmap views","You can add custom fields to track information like status or priority","A project can only include issues from one specific repository","The new Projects works identically to Projects (Classic) in every way"],"a":[0,1],"n":2,"e":"Projectsは複数レイアウトとカスタムフィールドに対応。組織単位で複数リポジトリを横断でき、Classicとは操作性が異なる。","eEn":"Projects supports multiple layouts and custom fields, can span multiple repositories at the org level, and differs from Classic in operation."},{"d":"D6","q":"組織の管理者が、フィッシング詐欺による被害の増加を受けて、メンバーのアカウント乗っ取りリスクを下げるためにサインイン方法とアクセス権限の見直しを進めています。次の記述のうち、正しいものを2つ選んでください。","qEn":"An organization admin is reviewing sign-in methods and access permissions to reduce the risk of account takeover. Select 2 correct statements.","o":["2要素認証(2FA)を有効にすることでアカウントの安全性を高められる","パスキーを使うと、生体認証やセキュリティキーでパスワードなしにサインインできる","Organizationのすべてのメンバーは自動的にAdmin(管理者)ロールを持つ","リポジトリの可視性をPrivateからPublicへ変更すると、Star数とWatcher数はリセットされる"],"oEn":["Enabling two-factor authentication (2FA) increases account security","Passkeys allow signing in without a password using biometrics or a security key","All organization members automatically hold the Admin role","Changing a repository's visibility from private to public resets its star and watcher counts"],"a":[0,1],"n":2,"e":"2FAとパスキーはアカウント保護策として正しい。メンバーが自動的に管理者になることはなく、可視性変更でStar等はリセットされない。","eEn":"2FA and passkeys are valid account protections; members do not automatically become admins, and visibility changes do not reset stars/watchers."},{"d":"D6","q":"セキュリティ担当者が、過去にリポジトリへ機密情報が混入した事例を受けて、機密情報の混入や既知の脆弱性を早期に検出する仕組みを整えようとしています。GitHubのセキュリティ機能に関する正しい記述を3つ選んでください。","qEn":"A security lead is setting up mechanisms to catch leaked secrets and known vulnerabilities early. Select 3 correct statements about GitHub's security features.","o":["Secret scanningはリポジトリ内にAPIキーなどの機密情報が誤ってコミットされていないかを検出する","Code scanningはCodeQLなどのツールを使いコード内の脆弱性やバグを検出する","Dependabot alertsは既知の脆弱性を持つ依存関係について、メールのみで通知しSecurityタブには表示されない","Push protectionは機密情報を検出した場合、pushが完了する前にブロックできる"],"oEn":["Secret scanning detects credentials like API keys accidentally committed to a repository","Code scanning uses tools such as CodeQL to detect vulnerabilities and bugs in code","Dependabot alerts notify only by email about known vulnerable dependencies and never appear in the Security tab","Push protection can block a push before it completes if it detects a secret"],"a":[0,1,3],"n":3,"e":"Secret scanning、Code scanning、Push protectionの説明は正しい。Dependabot alertsはSecurityタブにも表示される。","eEn":"Secret scanning, code scanning, and push protection are described correctly; Dependabot alerts also appear in the repository's Security tab."},{"d":"D7","q":"オープンソースコミュニティの立ち上げを新たに担当するメンバーが、利用者同士が気軽に質問や雑談をできる場と、開発者への金銭的支援の仕組みについて調べています。次の記述のうち、正しいものを2つ選んでください。","qEn":"A member launching an open-source community is researching a place for casual questions and discussion, plus a way to receive financial support as a developer. Select 2 correct statements.","o":["GitHub Discussionsは、Issueほど厳密でないオープンな議論や質問・アイデア共有の場として使える","GitHub Sponsorsを使うと、開発者はOSSへの貢献に対して金銭的な支援を受けられる","GitHub Pagesはリポジトリの内容をもとに動的なサーバーサイド処理を実行できる","Gistを公開(public)で作成すると、検索エンジンには一切表示されず常に非公開URLでのみアクセスできる"],"oEn":["GitHub Discussions can serve as an open space for less formal discussion, questions, and ideas than issues","GitHub Sponsors lets developers receive financial support for their open-source contributions","GitHub Pages can execute dynamic server-side processing based on repository content","A public gist is never shown by search engines and is only reachable via a private URL"],"a":[0,1],"n":2,"e":"DiscussionsとSponsorsの説明は正しい。GitHub Pagesは静的サイトのホスティングであり、公開Gistは検索や閲覧が可能。","eEn":"Discussions and Sponsors are described correctly. GitHub Pages hosts static sites only, and public gists are discoverable, not private."}];
const GH900_DND = [{"d":"D1","q":"次のGitHubプランを、主な対象となる利用者に対応させてください。","qEn":"Match each GitHub plan to the user group it is primarily designed for.","items":[{"id":"i1","text":"GitHub Free","textEn":"GitHub Free"},{"id":"i2","text":"GitHub Pro","textEn":"GitHub Pro"},{"id":"i3","text":"GitHub Team","textEn":"GitHub Team"},{"id":"i4","text":"GitHub Enterprise","textEn":"GitHub Enterprise"}],"targets":[{"id":"t1","label":"個人の開発者向け(無料または個人の有料機能)","labelEn":"Individual developers (free or personal paid tier)"},{"id":"t2","label":"共同作業ツールが必要な組織・チーム向け","labelEn":"Organizations/teams needing collaboration tools"},{"id":"t3","label":"高度なセキュリティ・コンプライアンス・サポートが必要な大企業向け","labelEn":"Large enterprises needing advanced security, compliance, and support"}],"correct":{"i1":"t1","i2":"t1","i3":"t2","i4":"t3"},"e":"GitHub Free は個人アカウントと組織の両方で利用できる無料プランで、個人開発者の基本用途に向いています。GitHub Pro はプロフェッショナルな個人開発者向けの追加機能(高度なコードレビューツールなど)を提供します。GitHub Team は複数人での共同作業に必要なブランチ保護やチーム管理機能を提供する組織向けプランです。GitHub Enterprise はSSO、監査ログ、GitHub Advanced Securityなど大企業のセキュリティ・コンプライアンス要件に応える最上位プランです。","eEn":"GitHub Free is a free plan available to both personal accounts and organizations, suited to individual developers' basic needs. GitHub Pro adds features for professional individual developers. GitHub Team is an organization plan providing collaboration features such as branch protection and team management. GitHub Enterprise is the top-tier plan offering SSO, audit logs, and GitHub Advanced Security for large enterprises' security and compliance needs."},{"d":"D3","q":"次のGitHub機能を、それぞれが主に果たす役割に対応させてください。","qEn":"Match each GitHub feature to the role it primarily serves.","items":[{"id":"i1","text":"Issues","textEn":"Issues"},{"id":"i2","text":"Projects","textEn":"Projects"},{"id":"i3","text":"Pull Request","textEn":"Pull Request"},{"id":"i4","text":"GitHub Actions","textEn":"GitHub Actions"},{"id":"i5","text":"Discussions","textEn":"Discussions"}],"targets":[{"id":"t1","label":"作業項目(バグ・タスク・要望など)の追跡と整理","labelEn":"Tracking and organizing work items (bugs, tasks, requests)"},{"id":"t2","label":"コードの変更内容をレビューし、ブランチへ統合する","labelEn":"Reviewing code changes and integrating them into a branch"},{"id":"t3","label":"自動化やチーム内のオープンな会話を支援する","labelEn":"Supporting automation and open team conversation"}],"correct":{"i1":"t1","i2":"t1","i3":"t2","i4":"t3","i5":"t3"},"e":"Issues はバグ報告やタスクの追跡に使われ、Projects はそれらをボードやテーブルで整理・可視化するための機能です。Pull Request はコードの変更をレビューし、承認を経てブランチにマージするための仕組みです。GitHub Actions はCI/CDなどのワークフローを自動化し、Discussions はIssueほど厳密でないオープンな質問や議論の場を提供します。","eEn":"Issues are used to report bugs and track tasks, while Projects organize and visualize them on boards or tables. Pull Requests are the mechanism for reviewing code changes and merging them into a branch after approval. GitHub Actions automates workflows such as CI/CD, and Discussions provide an open space for questions and conversation that is less formal than Issues."},{"d":"D6","q":"次のGitHubセキュリティ機能を、それぞれの用途に対応させてください。","qEn":"Match each GitHub security feature to its purpose.","items":[{"id":"i1","text":"コードスキャン(CodeQLなど)","textEn":"Code scanning (e.g., CodeQL)"},{"id":"i2","text":"シークレットスキャン","textEn":"Secret scanning"},{"id":"i3","text":"プッシュ保護(push protection)","textEn":"Push protection"},{"id":"i4","text":"Dependabotアラート","textEn":"Dependabot alerts"},{"id":"i5","text":"Dependabotセキュリティアップデート","textEn":"Dependabot security updates"}],"targets":[{"id":"t1","label":"コード自体に潜む脆弱性やバグを検出する","labelEn":"Detecting vulnerabilities and bugs in the code itself"},{"id":"t2","label":"リポジトリ内の、または新たにプッシュされる漏洩シークレットを検出・防止する","labelEn":"Detecting and preventing leaked secrets already in the repository or newly pushed"},{"id":"t3","label":"依存関係(サードパーティライブラリ)の脆弱性を検出し、更新を提案する","labelEn":"Detecting vulnerabilities in dependencies and proposing updates"}],"correct":{"i1":"t1","i2":"t2","i3":"t2","i4":"t3","i5":"t3"},"e":"コードスキャンはCodeQLなどのエンジンでソースコードの脆弱性やコーディングエラーを検出します。シークレットスキャンはリポジトリの履歴に含まれる漏洩した認証情報を検出し、プッシュ保護はプッシュ時点で高確度のシークレットを検知してプッシュ自体をブロックします。Dependabotアラートは依存関係の既知の脆弱性を通知し、Dependabotセキュリティアップデートは修正済みバージョンへの更新プルリクエストを自動作成します。","eEn":"Code scanning uses engines like CodeQL to detect vulnerabilities and coding errors in source code. Secret scanning detects leaked credentials already in the repository's history, while push protection blocks a push in real time when a high-confidence secret is detected. Dependabot alerts notify you of known vulnerabilities in dependencies, and Dependabot security updates automatically open pull requests upgrading to a fixed version."},{"d":"D4","q":"GitHub Actionsの用語を、それぞれの説明に対応させてください。","qEn":"Match each GitHub Actions term to its description.","items":[{"id":"i1","text":"Workflow","textEn":"Workflow"},{"id":"i2","text":"Job","textEn":"Job"},{"id":"i3","text":"Step","textEn":"Step"},{"id":"i4","text":"Action","textEn":"Action"}],"targets":[{"id":"t1","label":"いつ・何をトリガーに自動化を実行するかを定義する全体のプロセス","labelEn":"The overall automated process defining when and on what trigger it runs"},{"id":"t2","label":"ランナー上で順番に実行される、一連のステップをまとめた実行単位","labelEn":"An execution unit made of a sequence of steps that run on a runner"},{"id":"t3","label":"ジョブの中で実行される個々のコマンド、または再利用可能な処理","labelEn":"An individual command or reusable task executed within a job"}],"correct":{"i1":"t1","i2":"t2","i3":"t3","i4":"t3"},"e":"Workflowは.github/workflowsディレクトリ内のYAMLファイルで定義され、pushやpull_requestなどのイベントをトリガーに実行される自動化プロセス全体を指します。Jobはワークフロー内の実行単位で、既定では並列に実行され、それぞれ専用のランナー(仮想マシン)上で動きます。StepはJob内で順に実行される個々のタスクで、シェルコマンドを実行するか、再利用可能な処理単位であるActionを呼び出します。","eEn":"A workflow is defined in a YAML file under the .github/workflows directory and represents the entire automated process triggered by events such as push or pull_request. A job is an execution unit within a workflow; jobs run in parallel by default, each on its own runner (virtual machine). A step is an individual task run in sequence within a job, either running a shell command or invoking a reusable unit of work called an action."},{"d":"D7","q":"次のコミュニティ関連のファイル・機能を、それぞれの目的に対応させてください。","qEn":"Match each community-related file or feature to its purpose.","items":[{"id":"i1","text":"CODE_OF_CONDUCT.md","textEn":"CODE_OF_CONDUCT.md"},{"id":"i2","text":"CONTRIBUTING.md","textEn":"CONTRIBUTING.md"},{"id":"i3","text":"CODEOWNERSファイル","textEn":"CODEOWNERS file"},{"id":"i4","text":"GitHub Discussions","textEn":"GitHub Discussions"}],"targets":[{"id":"t1","label":"コミュニティの行動規範や貢献ガイドラインを文書化する(コミュニティ・ヘルスファイル)","labelEn":"Documenting the community's code of conduct and contribution guidelines (community health files)"},{"id":"t2","label":"特定のファイルやディレクトリが変更されたときにレビュー担当者を自動的に割り当てる","labelEn":"Automatically assigning reviewers when specific files or directories change"},{"id":"t3","label":"Issueほど形式張らない、オープンな質問や意見交換の場を提供する","labelEn":"Providing an open space for questions and discussion, less formal than Issues"}],"correct":{"i1":"t1","i2":"t1","i3":"t2","i4":"t3"},"e":"CODE_OF_CONDUCT.md と CONTRIBUTING.md はコミュニティ・ヘルスファイルと呼ばれ、それぞれ行動規範と貢献方法のガイドラインを示します。CODEOWNERSファイルはリポジトリ内の特定パスの変更時に指定した人・チームをレビュー担当者として自動的にプルリクエストへ追加します。GitHub DiscussionsはIssueのような厳密な作業追跡ではなく、質問や雑談を含むオープンな会話のための場です。","eEn":"CODE_OF_CONDUCT.md and CONTRIBUTING.md are community health files that document the code of conduct and contribution guidelines, respectively. The CODEOWNERS file automatically adds designated people or teams as reviewers on a pull request when specific paths in the repository are changed. GitHub Discussions is a space for open conversation, including questions and casual talk, rather than the strict work-tracking of Issues."},{"d":"D2","q":"次のGitおよびGitHubの操作を、それぞれの目的に対応させてください。","qEn":"Match each Git/GitHub operation to its purpose.","items":[{"id":"i1","text":"git clone","textEn":"git clone"},{"id":"i2","text":"Fork","textEn":"Fork"},{"id":"i3","text":"git commit","textEn":"git commit"},{"id":"i4","text":"git push","textEn":"git push"}],"targets":[{"id":"t1","label":"リモートリポジトリの内容をローカル環境に複製する","labelEn":"Copying the contents of a remote repository to a local environment"},{"id":"t2","label":"自分のアカウント配下にリポジトリの独立したコピーを作成する(GitHub上の操作)","labelEn":"Creating an independent copy of a repository under your own account (a GitHub-side operation)"},{"id":"t3","label":"変更を記録し、リモートリポジトリへ反映する","labelEn":"Recording changes and reflecting them to the remote repository"}],"correct":{"i1":"t1","i2":"t2","i3":"t3","i4":"t3"},"e":"git clone はリモートリポジトリの内容をローカルにダウンロードして複製するコマンドです。Fork はGitHub上で他者のリポジトリの独立したコピーを自分のアカウント配下に作成する操作で、書き込み権限がない場合の貢献手順の第一歩になります。git commit はステージした変更をローカルの履歴に記録し、git push はそのコミットをリモートリポジトリに反映します。","eEn":"git clone downloads and copies the contents of a remote repository to your local machine. Fork is a GitHub-side operation that creates an independent copy of someone else's repository under your own account, typically the first step of contributing when you lack write access. git commit records staged changes to the local history, and git push sends those commits to the remote repository."}];
const GH900_BUILD = [{"d":"D2","q":"ローカルで行った変更をGitHubのリモートリポジトリに反映し、プルリクエストとしてマージするまでの正しい手順に並び替えてください。","qEn":"Arrange the steps in the correct order to reflect a local change to the GitHub remote repository and merge it via a pull request.","candidates":[{"id":"c1","text":"変更したファイルをステージし、`git commit` でローカル履歴に記録する","textEn":"Stage the changed files and record them to the local history with `git commit`"},{"id":"c2","text":"`git push` でリモートリポジトリにブランチを反映する","textEn":"Push the branch to the remote repository with `git push`"},{"id":"c3","text":"GitHub上でプルリクエストを作成する","textEn":"Create a pull request on GitHub"},{"id":"c4","text":"レビューを受けて承認された後、プルリクエストをマージする","textEn":"After the review is approved, merge the pull request"},{"id":"c5","text":"リポジトリを新規に作成する","textEn":"Create a new repository"},{"id":"c6","text":"mainブランチを削除して作業をやり直す","textEn":"Delete the main branch and start the work over"}],"answer":["c1","c2","c3","c4"],"e":"変更を反映するには、まずステージしてコミット(git commit)としてローカルに記録し、push でリモートに送信します。その後GitHub上でプルリクエストを作成し、レビューと承認を経てマージします。「リポジトリを新規作成する」と「mainブランチを削除する」は既存プロジェクトへの変更フローには不要・不適切な手順です。","eEn":"To reflect a change, you first stage and record it locally as a commit (git commit), and send it to the remote with push. Then you create a pull request on GitHub, and after review and approval, merge it. 'Create a new repository' and 'delete the main branch' are not part of, or are harmful to, this change flow for an existing project."},{"d":"D3","q":"書き込み権限を持たない他者のオープンソースリポジトリに貢献する場合の、正しい手順に並び替えてください。","qEn":"Arrange the correct steps for contributing to someone else's open-source repository when you do not have write access.","candidates":[{"id":"c1","text":"対象リポジトリをFork(フォーク)して自分のアカウントにコピーする","textEn":"Fork the target repository to copy it to your own account"},{"id":"c2","text":"Forkしたリポジトリをローカルにclone(クローン)する","textEn":"Clone the forked repository to your local machine"},{"id":"c3","text":"作業用の新しいブランチを作成し、変更をコミットして自分のForkへpushする","textEn":"Create a new working branch, commit the change, and push it to your fork"},{"id":"c4","text":"元のリポジトリに向けてプルリクエストを作成する","textEn":"Open a pull request against the original repository"},{"id":"c5","text":"元のリポジトリの管理者権限を付与してもらう","textEn":"Have the original repo's admin grant you admin rights"},{"id":"c6","text":"元のリポジトリのmainブランチに直接pushする","textEn":"Push directly to the main branch of the original repository"}],"answer":["c1","c2","c3","c4"],"e":"書き込み権限がない場合、まずForkして自分のアカウント配下に独立したコピーを作成し、それをcloneしてローカルで作業します。作業用ブランチを作成してから変更をコミットし、自分のForkにpushした後、元のリポジトリ(upstream)に向けてプルリクエストを作成します。管理者権限の付与や、権限のない元リポジトリへの直接pushは、書き込み権限を持たない貢献者には行えない手順です。","eEn":"Without write access, you first fork the repository to create an independent copy under your own account, then clone it locally. After creating a working branch, you commit your changes, push them to your fork, and open a pull request against the original (upstream) repository. Being granted admin rights, or pushing directly to the original repository without write access, are not actions available to a contributor in this situation."},{"d":"D4","q":"GitHubリポジトリにCIを行うGitHub Actionsワークフローを新規に作成する手順を、正しい順序に並び替えてください。","qEn":"Arrange the steps in the correct order for creating a new GitHub Actions workflow that runs CI in a repository.","candidates":[{"id":"c1","text":"リポジトリの `.github/workflows` ディレクトリに新しいYAMLファイルを作成する","textEn":"Create a new YAML file in the repository's `.github/workflows` directory"},{"id":"c2","text":"`on` でトリガーイベント(pushやpull_requestなど)を定義し、`jobs` の中に実行するジョブと各ジョブの `steps` を定義する","textEn":"Define the triggering event(s) (e.g., push, pull_request) with `on`, and define the jobs and each job's `steps` under `jobs`"},{"id":"c3","text":"変更をコミットしてリポジトリにpushする","textEn":"Commit the change and push it to the repository"},{"id":"c4","text":"Actionsタブでワークフローの実行結果を確認する","textEn":"Check the workflow run result in the Actions tab"},{"id":"c5","text":"ワークフローファイルをリポジトリのルートディレクトリに置く","textEn":"Place the workflow file in the repository's root directory"},{"id":"c6","text":"ワークフローファイルの拡張子を `.actions` にする","textEn":"Give the workflow file a `.actions` extension"}],"answer":["c1","c2","c3","c4"],"e":"ワークフローは `.github/workflows` ディレクトリ内のYAMLファイルとして作成する必要があります。ファイル内では `on` でトリガーとなるイベントを、`jobs` で実行するジョブとその `steps` を定義します。定義後にコミット・pushすると、条件に一致するイベント発生時にワークフローが実行され、Actionsタブで結果を確認できます。ワークフローファイルをリポジトリのルートに置くことや、`.yml`/`.yaml` 以外の拡張子を付けることは、GitHubに認識されないため誤りです。","eEn":"A workflow must be created as a YAML file inside the `.github/workflows` directory. Within the file, `on` defines the triggering event(s), and `jobs` defines the jobs to run along with their `steps`. After committing and pushing, the workflow runs when a matching event occurs, and you can check the result in the Actions tab. Placing the workflow file at the repository root, or giving it an extension other than `.yml`/`.yaml`, is incorrect since GitHub will not recognize it."},{"d":"D3","q":"報告されたバグをIssueとして起票してから修正が完了するまでの、正しい手順に並び替えてください。","qEn":"Arrange the correct steps from filing a bug as an Issue through completing the fix.","candidates":[{"id":"c1","text":"バグの内容をIssueとして起票する","textEn":"File the bug as an Issue"},{"id":"c2","text":"修正用の新しいブランチを作成し、Issue番号を参照するコミットメッセージで修正をコミットする(例: `Fixes #123`)","textEn":"Create a new branch for the fix and commit it with a message referencing the Issue number (e.g., `Fixes #123`)"},{"id":"c3","text":"プルリクエストを作成してレビューを依頼する","textEn":"Open a pull request and request a review"},{"id":"c4","text":"プルリクエストがマージされ、参照されたIssueが自動的にクローズされる","textEn":"The pull request is merged, and the referenced Issue is automatically closed"},{"id":"c5","text":"Issueをラベル管理者権限で削除する","textEn":"Delete the Issue using label-admin permissions"},{"id":"c6","text":"IssueをWikiページに転記して手動でクローズする","textEn":"Transcribe the Issue to a wiki page and close it manually"}],"answer":["c1","c2","c3","c4"],"e":"バグ報告はまずIssueとして起票し、修正用のブランチを作成します。コミットメッセージやプルリクエストの本文で `Fixes #123` のようにIssue番号を参照すると、そのプルリクエストがデフォルトブランチにマージされた際に対応するIssueが自動的にクローズされます。Issueの削除やWikiへの転記は通常の修正フローには含まれません。","eEn":"A bug report is first filed as an Issue, then a branch is created for the fix. Referencing the Issue number in the commit message or pull request body, such as `Fixes #123`, causes the linked Issue to be automatically closed when the pull request is merged into the default branch. Deleting the Issue or transcribing it to a wiki page is not part of the normal fix workflow."},{"d":"D5","q":"チームの作業を可視化するために新しいGitHub Projectを作成し、Issueを管理できる状態にするまでの手順に並び替えてください。","qEn":"Arrange the steps for creating a new GitHub Project to visualize team work and getting it ready to manage Issues.","candidates":[{"id":"c1","text":"新しいProject(プロジェクト)を作成する","textEn":"Create a new Project"},{"id":"c2","text":"既存のIssueやプルリクエストをプロジェクトに追加する","textEn":"Add existing Issues or pull requests to the project"},{"id":"c3","text":"Status(ステータス)などのカスタムフィールドで各項目の進行状況を設定する","textEn":"Set the progress of each item using custom fields such as Status"},{"id":"c4","text":"ビュー(ボードやテーブルなど)を使って作業の進捗を確認する","textEn":"Use views (such as board or table) to check the progress of the work"},{"id":"c5","text":"テンプレートからリポジトリ全体を複製する","textEn":"Duplicate the entire repository from a template"}],"answer":["c1","c2","c3","c4"],"e":"まず新しいProjectを作成し、対象のIssueやプルリクエストを追加します。次にStatusなどのフィールドで各項目の進行状況(Todo/In Progress/Doneなど)を設定し、ボードビューやテーブルビューを使って全体の進捗を可視化します。テンプレートからのリポジトリ複製はProjectのセットアップとは無関係です。","eEn":"You first create a new Project and add the relevant Issues or pull requests to it. Then you set each item's progress (e.g., Todo/In Progress/Done) using fields such as Status, and use board or table views to visualize overall progress. Duplicating a repository from a template is unrelated to setting up a Project."},{"d":"D6","q":"リポジトリでDependabotアラートを有効化してから、検出された脆弱性への対応を完了するまでの手順に並び替えてください。","qEn":"Arrange the steps from enabling Dependabot alerts on a repository through resolving a detected vulnerability.","candidates":[{"id":"c1","text":"リポジトリの設定でDependabotアラートを有効化する","textEn":"Enable Dependabot alerts in the repository settings"},{"id":"c2","text":"依存関係の脆弱性についてのアラートを確認する","textEn":"Review the alert about the vulnerable dependency"},{"id":"c3","text":"Dependabotが作成した、修正済みバージョンへ更新するプルリクエストをレビューする","textEn":"Review the pull request Dependabot opened to update to a fixed version"},{"id":"c4","text":"プルリクエストをマージし、アラートを解消する","textEn":"Merge the pull request to resolve the alert"},{"id":"c5","text":"リポジトリを非公開から公開に変更する","textEn":"Change the repository from private to public"}],"answer":["c1","c2","c3","c4"],"e":"まずDependabotアラートを有効化し、脆弱な依存関係が検出されたらアラート内容を確認します。Dependabotセキュリティアップデートが有効な場合、修正済みバージョンへの更新プルリクエストが自動作成されるため、それをレビューしてマージすることでアラートが解消されます。リポジトリの公開設定変更はこの対応には関係ありません。","eEn":"You first enable Dependabot alerts, and when a vulnerable dependency is detected, you review the alert. If Dependabot security updates are enabled, a pull request upgrading to a fixed version is automatically opened; reviewing and merging it resolves the alert. Changing the repository's visibility is unrelated to this process."}];

const GH900_EXHIBIT = [{"d":"D3","q":"あるオープンソースリポジトリに、Issueへのラベル付けやPull Requestのレビュアー割り当ては行うものの、コードのpushやリポジトリ設定の変更はさせたくない外部の協力者がいます。付与すべき最小限のロールはどれですか？","qEn":"You want an outside collaborator on an open-source repository to be able to label issues and assign PR reviewers, but must not be able to push code or change repository settings. Which minimum role should you grant?","exhibits":[{"id":"e1","tab":"リポジトリロール権限一覧","tabEn":"Repository role permissions","kind":"table","table":{"headers":["ロール","Clone/Pull","Issue/PRを開く","ラベル付け・担当者割当","コードのpush","リポジトリ設定変更"],"headersEn":["Role","Clone/Pull","Open issues/PRs","Label & assign reviewers","Push code","Change repo settings"],"rows":[["Read","○","○","×","×","×"],["Triage","○","○","○","×","×"],["Write","○","○","○","○","×"],["Admin","○","○","○","○","○"]],"rowsEn":[["Read","Yes","Yes","No","No","No"],["Triage","Yes","Yes","Yes","No","No"],["Write","Yes","Yes","Yes","Yes","No"],["Admin","Yes","Yes","Yes","Yes","Yes"]]}}],"o":["Read","Triage","Write（コードのpush権限を含むロール）","Admin"],"oEn":["Read","Triage","Write, a role that includes push access to code","Admin"],"a":1,"e":"Triageロールは、コードのpush権限を与えずにIssueとPull Requestの管理（ラベル付け、担当者割当など）を行える権限です。表の通りTriageは「push」と「設定変更」が×のため、要件を満たす最小権限です。","eEn":"The Triage role lets a collaborator manage issues and pull requests (labels, assignees) without granting push access. As shown in the table, Triage has 'No' for both push and settings, making it the minimum role that satisfies the requirement."},{"d":"D4","q":"次のワークフローファイルについて、このワークフローが実行され「ない」組み合わせはどれですか？","qEn":"Given the following workflow file, which of the following situations would NOT trigger this workflow?","exhibits":[{"id":"e1","tab":"ci.yml","tabEn":"ci.yml","kind":"text","text":"name: CI\non:\n  push:\n    branches: [ main ]\n    paths:\n      - '**.py'\n  pull_request:\n    branches: [ main ]\n    paths:\n      - '**.py'\njobs:\n  test:\n    runs-on: ubuntu-latest\n    steps:\n      - uses: actions/checkout@v4\n      - name: Run tests\n        run: pytest -q\n","textEn":"name: CI\non:\n  push:\n    branches: [ main ]\n    paths:\n      - '**.py'\n  pull_request:\n    branches: [ main ]\n    paths:\n      - '**.py'\njobs:\n  test:\n    runs-on: ubuntu-latest\n    steps:\n      - uses: actions/checkout@v4\n      - name: Run tests\n        run: pytest -q\n"}],"o":["mainブランチへのpushで app.py を変更した","mainブランチへのPull Requestで README.md のみを変更した","mainブランチへのPull Requestで utils.py を変更した","mainブランチへのpushで tests/test_app.py を変更した（テスト配下のファイルのみの変更）"],"oEn":["A push to main that modifies app.py","A pull request targeting main that modifies only README.md","A pull request targeting main that modifies utils.py","A push to main that modifies tests/test_app.py (a change under the tests directory only)"],"a":1,"e":"on.push と on.pull_request の両方に paths: ['**.py'] が指定されているため、.pyファイルを含まない変更（README.mdのみ）ではワークフローはトリガーされません。他の選択肢はすべて.pyファイルの変更を含むためトリガーされます。","eEn":"Both the push and pull_request triggers are filtered with paths: ['**.py']. A change that touches only README.md does not match this path filter, so the workflow does not run. All other options modify a .py file and therefore do trigger the workflow."},{"d":"D6","q":"GitHub Advanced Securityのライセンスを持たないプライベートリポジトリの管理者が、次の表をもとに利用できるセキュリティ機能を確認しています。正しい説明はどれですか？","qEn":"The admin of a private repository without a GitHub Advanced Security license reviews the following table. Which statement is correct?","exhibits":[{"id":"e1","tab":"セキュリティ機能の提供範囲","tabEn":"Security feature availability","kind":"table","table":{"headers":["機能","パブリックリポジトリ","プライベートリポジトリ（GHASなし）"],"headersEn":["Feature","Public repository","Private repository (no GHAS)"],"rows":[["Dependabotアラート","利用可能","利用可能"],["シークレットスキャン","利用可能","GHASが必要"],["コードスキャン(CodeQL)","利用可能","GHASが必要"]],"rowsEn":[["Dependabot alerts","Available","Available"],["Secret scanning","Available","Requires GHAS"],["Code scanning (CodeQL)","Available","Requires GHAS"]]}}],"o":["Dependabotアラートも CodeQL のコードスキャンも、GHASのライセンスなしでプライベートリポジトリでそのまま使える","Dependabotアラートは使えるが、CodeQLによるコードスキャンにはGHASが必要である","どちらの機能も利用するにはGHASが必須である","プライベートリポジトリではセキュリティ機能は一切利用できない"],"oEn":["Both Dependabot alerts and CodeQL code scanning work on private repositories without a GHAS license","Dependabot alerts work without GHAS, but CodeQL code scanning requires GHAS","Both features strictly require GHAS","No security feature is available on private repositories at all"],"a":1,"e":"表の通り、Dependabotアラートはリポジトリの可視性に関係なく利用できますが、コードスキャン（CodeQL）はプライベートリポジトリではGitHub Advanced Securityのライセンスが必要です。","eEn":"As shown in the table, Dependabot alerts are available regardless of repository visibility, while CodeQL code scanning on a private repository requires a GitHub Advanced Security license."},{"d":"D5","q":"本日は2026-08-03です。次のマイルストーン一覧の表を見て、期限に対して最もリスクが高い（遅延の可能性が高い）マイルストーンはどれですか？","qEn":"Today is 2026-08-03. Based on the milestone table below, which milestone is at the highest risk of missing its due date?","exhibits":[{"id":"e1","tab":"マイルストーン一覧","tabEn":"Milestones","kind":"table","table":{"headers":["マイルストーン","期限","オープンなIssue","クローズ済みIssue"],"headersEn":["Milestone","Due date","Open issues","Closed issues"],"rows":[["v1.0 Release","2026-08-10","8","2"],["v1.1 Backlog","2026-09-30","3","1"],["Docs Refresh","2026-08-05","1","9"]],"rowsEn":[["v1.0 Release","2026-08-10","8","2"],["v1.1 Backlog","2026-09-30","3","1"],["Docs Refresh","2026-08-05","1","9"]]}}],"o":["v1.0 Release","v1.1 Backlog","Docs Refresh","すべて同程度に低リスク"],"oEn":["v1.0 Release","v1.1 Backlog","Docs Refresh","All are equally low risk"],"a":0,"e":"v1.0 Releaseは期限まで残り7日しかないのに、Issueの8割(8/10)が未クローズで進捗が遅れています。Docs Refreshは期限が近い（2日後）ものの9割完了しており低リスク、v1.1 Backlogは期限に余裕があります。","eEn":"v1.0 Release has only 7 days left but 8 of 10 issues (80%) are still open, indicating it is behind schedule. Docs Refresh is due soon (in 2 days) but is 90% complete, so it is low risk, and v1.1 Backlog has ample time remaining."},{"d":"D1","q":"リモートリポジトリの最新のコミット情報を確認したいですが、現在の作業ブランチには一切変更を加えたくありません。表を参考に、使うべきコマンドはどれですか？","qEn":"You want to check the latest commit information on the remote repository, but you must not change your current working branch at all. Based on the table, which command should you use?","exhibits":[{"id":"e1","tab":"主要なgitコマンドの比較","tabEn":"Comparison of key git commands","kind":"table","table":{"headers":["コマンド","作業ブランチを変更するか","リモートへ変更を送るか","主な用途"],"headersEn":["Command","Changes working branch?","Sends changes to remote?","Typical use"],"rows":[["git clone","新規作成","しない","初回にリポジトリを取得する"],["git fetch","しない","しない","リモートの最新情報のみ取得する"],["git pull","する（マージ/リベース）","しない","フェッチ＋マージを行う"],["git push","しない","する","ローカルの変更をリモートへ送信する"]],"rowsEn":[["git clone","Creates new local copy","No","Get a repository for the first time"],["git fetch","No","No","Retrieve latest info from remote only"],["git pull","Yes (merge/rebase)","No","Fetch + merge in one step"],["git push","No","Yes","Send local commits to the remote"]]}}],"o":["git clone","git fetch","git pull","git push"],"oEn":["git clone","git fetch","git pull","git push"],"a":1,"e":"git fetchはリモートの最新の参照情報をローカルに取り込みますが、現在の作業ブランチには一切マージやリベースを行いません。git pullはfetchに加えてマージ/リベースを行うため作業ブランチが変わってしまいます。","eEn":"git fetch downloads the latest refs and objects from the remote without merging or rebasing into your current working branch. git pull would also merge/rebase, which changes the working branch — not what is required here."}];
const GH900_MATRIX = [{"d":"D2","scenario":"リポジトリ管理者は、mainブランチに対して以下のブランチ保護ルールを設定しました。その後、あるメンバーがmainへ直接pushしようとしたところ拒否され、別のPull Requestは2名の承認とCIの成功を経てマージされました。","scenarioEn":"A repository admin configured the following branch protection rule on main. Afterward, a member's attempt to push directly to main was rejected, while a separate pull request was merged after receiving 2 approvals and a passing CI check.","exhibits":[{"id":"e1","tab":"mainブランチの保護ルール設定","tabEn":"Branch protection settings for main","kind":"table","table":{"headers":["設定項目","値"],"headersEn":["Setting","Value"],"rows":[["マージ前にPull Requestを必須にする","有効"],["必要な承認数","2"],["ステータスチェック(CI)の成功を必須にする","有効"],["force pushの許可","無効"]],"rowsEn":[["Require a pull request before merging","Enabled"],["Required approving reviews","2"],["Require status checks (CI) to pass","Enabled"],["Allow force pushes","Disabled"]]}},{"id":"e2","tab":"リポジトリ操作ログ（抜粋）","tabEn":"Repository activity log (excerpt)","kind":"text","text":"2026-08-01 10:12  user:sato   push to main (direct)   -> rejected: protected branch\n2026-08-02 09:40  user:tanaka open PR #42 feature/login -> main\n2026-08-02 15:03  review: approved by suzuki (1/2)\n2026-08-03 09:00  review: approved by yamada (2/2)\n2026-08-03 09:05  check: CI (build-and-test) -> success\n2026-08-03 09:06  PR #42 merged into main\n","textEn":"2026-08-01 10:12  user:sato   push to main (direct)   -> rejected: protected branch\n2026-08-02 09:40  user:tanaka open PR #42 feature/login -> main\n2026-08-02 15:03  review: approved by suzuki (1/2)\n2026-08-03 09:00  review: approved by yamada (2/2)\n2026-08-03 09:05  check: CI (build-and-test) -> success\n2026-08-03 09:06  PR #42 merged into main\n"}],"statements":[{"id":"s1","text":"現在の設定では、mainブランチへの直接pushは拒否される。","textEn":"With the current settings, a direct push to main is rejected."},{"id":"s2","text":"承認者が1名でもPull Requestをmainにマージできる。","textEn":"A pull request can be merged into main with only one approval."},{"id":"s3","text":"force pushはmainブランチに対して許可されている。","textEn":"Force pushes are allowed on the main branch."}],"correct":{"s1":"yes","s2":"no","s3":"no"},"e":"設定表より、mainは保護されており直接pushは拒否されます（ログでも実証済み）。必要な承認数は2のため1名の承認だけではマージできず、force pushも無効化されています。","eEn":"The settings table shows main is protected, so direct pushes are rejected (confirmed in the log). Since 2 approvals are required, one approval alone is insufficient to merge, and force pushes are disabled."},{"d":"D4","scenario":"チームは、production環境へのデプロイジョブを含むワークフローを設定し、production環境には保護ルールを設定しました。開発者がfeature/paymentブランチで作業を行い、その後mainにマージされました。","scenarioEn":"The team configured a workflow with a deployment job targeting the production environment, and set protection rules on that environment. A developer worked on the feature/payment branch, which was later merged into main.","exhibits":[{"id":"e1","tab":"deploy.yml（抜粋）","tabEn":"deploy.yml (excerpt)","kind":"text","text":"on:\n  push:\n    branches: [ main ]\njobs:\n  deploy:\n    runs-on: ubuntu-latest\n    environment: production\n    steps:\n      - name: Deploy\n        run: ./deploy.sh\n","textEn":"on:\n  push:\n    branches: [ main ]\njobs:\n  deploy:\n    runs-on: ubuntu-latest\n    environment: production\n    steps:\n      - name: Deploy\n        run: ./deploy.sh\n"},{"id":"e2","tab":"production環境の保護ルール","tabEn":"production environment protection rules","kind":"table","table":{"headers":["項目","設定値"],"headersEn":["Setting","Value"],"rows":[["必須レビュアー","alice, bob"],["待機タイマー","10分"],["デプロイ許可ブランチ","mainのみ"]],"rowsEn":[["Required reviewers","alice, bob"],["Wait timer","10 minutes"],["Deployment branch policy","main only"]]}}],"statements":[{"id":"s1","text":"productionへのデプロイ前に、指定されたレビュアーの承認が必要である。","textEn":"Deployment to production requires approval from the specified reviewers before it proceeds."},{"id":"s2","text":"feature/paymentブランチから直接pushしても、production環境へのjobを実行できる。","textEn":"Pushing directly to the feature/payment branch can trigger the job targeting the production environment."},{"id":"s3","text":"承認後、最低10分待ってからデプロイジョブが実行される。","textEn":"After approval, the deployment job runs only after waiting at least 10 minutes."}],"correct":{"s1":"yes","s2":"no","s3":"yes"},"e":"workflowはmainブランチへのpushでのみトリガーされ、production環境には必須レビュアーと10分の待機タイマーが設定されています。deployment branch policyがmainのみのため、feature/paymentから直接この環境向けjobは実行されません。","eEn":"The workflow only triggers on pushes to main, and the production environment requires reviewer approval plus a 10-minute wait timer. Since the deployment branch policy is restricted to main, the job targeting this environment cannot run directly from feature/payment."},{"d":"D6","scenario":"セキュリティ担当者は、あるリポジトリのDependabotアラート一覧とセキュリティ設定を確認しています。","scenarioEn":"A security engineer reviews a repository's Dependabot alerts list and its security settings.","exhibits":[{"id":"e1","tab":"Dependabotアラート一覧","tabEn":"Dependabot alerts","kind":"table","table":{"headers":["パッケージ","深刻度","状態"],"headersEn":["Package","Severity","Status"],"rows":[["lodash","High","Open"],["requests","Critical","Open"],["flask","Low","Dismissed"]],"rowsEn":[["lodash","High","Open"],["requests","Critical","Open"],["flask","Low","Dismissed"]]}},{"id":"e2","tab":"Code security and analysis 設定","tabEn":"Code security and analysis settings","kind":"table","table":{"headers":["機能","状態"],"headersEn":["Feature","Status"],"rows":[["Dependabotアラート","有効"],["Dependabotセキュリティアップデート","無効"],["シークレットスキャンのpush protection","有効"]],"rowsEn":[["Dependabot alerts","Enabled"],["Dependabot security updates","Disabled"],["Secret scanning push protection","Enabled"]]}}],"statements":[{"id":"s1","text":"requestsパッケージの脆弱性はCriticalであり、対応が必要である。","textEn":"The vulnerability in the requests package is Critical severity and needs attention."},{"id":"s2","text":"Dependabotセキュリティアップデートが有効なので、脆弱性を修正するPRが自動作成される。","textEn":"Because Dependabot security updates are enabled, a PR to fix the vulnerability is created automatically."},{"id":"s3","text":"シークレットスキャンのpush protectionが有効なため、シークレットを含むpushはブロックされうる。","textEn":"Because secret scanning push protection is enabled, a push containing a secret can be blocked."}],"correct":{"s1":"yes","s2":"no","s3":"yes"},"e":"requestsのアラートはCriticalでOpenのため対応が必要です。ただしDependabotセキュリティアップデートは無効になっているため、修正PRは自動作成されません（有効化が必要）。push protectionは有効なため、シークレットを含むpushはブロックされます。","eEn":"The requests alert is Critical and still Open, so it needs remediation. However, Dependabot security updates are disabled, so fix PRs are not created automatically (it would need to be enabled). Push protection is enabled, so pushes containing secrets can be blocked."},{"d":"D7","scenario":"OSSメンテナーは、プロジェクトを公開前に Insights > Community Standards ページでチェックリストを確認しています。","scenarioEn":"An OSS maintainer reviews the checklist on the Insights > Community Standards page before publicizing the project.","exhibits":[{"id":"e1","tab":"リポジトリのファイル一覧","tabEn":"Repository file listing","kind":"table","table":{"headers":["ファイル/フォルダ","存在するか"],"headersEn":["File/Folder","Present?"],"rows":[["README.md","あり"],["CONTRIBUTING.md","あり"],["CODE_OF_CONDUCT.md","なし"],["LICENSE","なし"],[".github/ISSUE_TEMPLATE/","あり"]],"rowsEn":[["README.md","Present"],["CONTRIBUTING.md","Present"],["CODE_OF_CONDUCT.md","Missing"],["LICENSE","Missing"],[".github/ISSUE_TEMPLATE/","Present"]]}},{"id":"e2","tab":"Community Standards チェックリスト","tabEn":"Community Standards checklist","kind":"table","table":{"headers":["項目","状態"],"headersEn":["Item","Status"],"rows":[["Description","✓"],["README","✓"],["Code of conduct","✗"],["Contributing","✓"],["License","✗"],["Issue templates","✓"]],"rowsEn":[["Description","✓"],["README","✓"],["Code of conduct","✗"],["Contributing","✓"],["License","✗"],["Issue templates","✓"]]}}],"statements":[{"id":"s1","text":"LICENSEファイルが存在しないため、Community Standardsのチェックリストは全項目を満たしていない。","textEn":"Because the LICENSE file is missing, the Community Standards checklist is not fully satisfied."},{"id":"s2","text":"CODE_OF_CONDUCTファイルはすでにこのリポジトリに追加されている。","textEn":"A CODE_OF_CONDUCT file has already been added to this repository."},{"id":"s3","text":"ISSUE_TEMPLATEが存在するため、Issue作成時にテンプレートを選択できる。","textEn":"Because ISSUE_TEMPLATE exists, contributors can choose a template when opening an issue."}],"correct":{"s1":"yes","s2":"no","s3":"yes"},"e":"チェックリストではCode of conductとLicenseの2項目が✗のため未達成です。CODE_OF_CONDUCT.mdはファイル一覧に存在しません。ISSUE_TEMPLATEフォルダがあるため、Issue作成時にテンプレート選択が可能です。","eEn":"The checklist shows both Code of conduct and License as unmet (✗). CODE_OF_CONDUCT.md does not appear in the file listing. Since the ISSUE_TEMPLATE folder exists, contributors can choose a template when filing an issue."}];
