function shuffleMultiBi(q, lang, salt) {
  const src = lang === "en" ? (q.oEn || q.o) : q.o;
  const n = src.length;
  let h = 0; const base = qKey(q) + "|m|" + salt;
  for (let i = 0; i < base.length; i++) { h = (h * 33 + base.charCodeAt(i)) | 0; }
  const perm = permFromSeed(n, h >>> 0);
  const opts = perm.map(i => src[i]);
  const a = q.a.map(orig => perm.indexOf(orig)).sort((x, y) => x - y);
  return { opts, a };
}
